    }

template <class KernelArgs>
        __device__ SplitKBatchOffset(const KernelArgs& kargs, const std::size_t k_id = blockIdx.z)
        {
            constexpr auto N1   = BlockGemmShape::WarpTile::at(number<1>{});
            constexpr auto K1   = BlockGemmShape::WarpTile::at(number<2>{});
            const index_t K_t   = kargs.k_batch * K1;
            const index_t KRead = (kargs.K + K_t - 1) / K_t * K1;

            if constexpr(std::is_same_v<tensor_layout::gemm::RowMajor, ALayout>)
            {
                a_k_split_offset = k_id * KRead;
            }
            else if constexpr(std::is_same_v<tensor_layout::gemm::ColumnMajor, ALayout>)
            {
                a_k_split_offset = k_id * KRead * kargs.stride_A;
            }

            if constexpr(std::is_same_v<tensor_layout::gemm::RowMajor, BLayout>)
            {
                b_k_split_offset = k_id * KRead * kargs.stride_B * N1;
            }
            else if constexpr(std::is_same_v<tensor_layout::gemm::ColumnMajor, BLayout>)
            {
                b_k_split_offset = k_id * KRead * N1;
            }

            if(k_id < static_cast<uint32_t>(kargs.k_batch - 1))
            {
                splitted_k = KRead;
            }
            else
            {
                splitted_k = kargs.K - KRead * (kargs.k_batch - 1);
            }
        }

template <class KernelArgs>
        __device__ SplitKBatchOffset(const KernelArgs& kargs, const std::size_t k_id = blockIdx.z)
        {
            constexpr auto K1   = BlockGemmShape::WarpTile::at(number<2>{});
            const index_t K_t   = kargs.k_batch * K1;
            const index_t KRead = (kargs.K + K_t - 1) / K_t * K1;

            if constexpr(std::is_same_v<tensor_layout::gemm::RowMajor, ALayout>)
            {
                a_k_split_offset = k_id * KRead;
            }
            else if constexpr(std::is_same_v<tensor_layout::gemm::ColumnMajor, ALayout>)
            {
                a_k_split_offset = k_id * KRead * kargs.stride_A;
            }

            if(k_id < static_cast<uint32_t>(kargs.k_batch - 1))
            {
                splitted_k = KRead;
            }
            else
            {
                splitted_k = kargs.K - KRead * (kargs.k_batch - 1);
            }

            if constexpr(IsBShuffled)
            {
                b_k_split_offset = k_id * splitted_k * NPerXdl;
            }
            else
            {
                if constexpr(std::is_same_v<tensor_layout::gemm::RowMajor, BLayout>)
                {
                    b_k_split_offset = k_id * KRead * kargs.stride_B;
                }
                else if constexpr(std::is_same_v<tensor_layout::gemm::ColumnMajor, BLayout>)
                {
                    b_k_split_offset = k_id * KRead;
                }
            }
        }

template <typename ADataType_,
          typename BDataType_,
          typename AccDataType,
          typename CDataType,
          typename LayoutA,
          typename LayoutB,
          typename LayoutC>
__global__ void naive_gemm_kernel(if_select_t<ADataType_, tf32_t, float, ADataType_>* A,
                                  if_select_t<BDataType_, tf32_t, float, BDataType_>* B,
                                  CDataType* C,
                                  ck_tile::index_t M,
                                  ck_tile::index_t N,
                                  ck_tile::index_t K,
                                  ck_tile::index_t strideA,
                                  ck_tile::index_t strideB,
                                  ck_tile::index_t strideC)
{
    if constexpr(std::is_same_v<ADataType_, tf32_t> || std::is_same_v<BDataType_, tf32_t>)
        static_assert(std::is_same_v<ADataType_, BDataType_>,
                      "ADataType and BDataType must be the same");
    using ADataTypeCompute = ADataType_;
    // ADataTypeBuf: buffer/storage type (fp32 when tf32)
    using ADataTypeBuf = if_select_t<ADataType_, tf32_t, float, ADataType_>;
    using BDataTypeBuf = if_select_t<BDataType_, tf32_t, float, BDataType_>;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int row = idx / N; // Compute row index
    int col = idx % N; // Compute column index

    if(row < M && col < N)
    {
        AccDataType acc = 0.0;
        for(int k = 0; k < K; ++k)
        {
            constexpr index_t packed_size_a = ck_tile::numeric_traits<ADataTypeBuf>::PackedSize;
            constexpr index_t packed_size_b = ck_tile::numeric_traits<BDataTypeBuf>::PackedSize;
            // Adjust indexing based on matrix layout
            int a_index = (std::is_same_v<LayoutA, tensor_layout::gemm::RowMajor>)
                              ? row * strideA + k
                              : k * strideA + row;
            int b_index = (std::is_same_v<LayoutB, tensor_layout::gemm::ColumnMajor>)
                              ? col * strideB + k
                              : k * strideB + col;

            AccDataType v_a;
            AccDataType v_b;
            if constexpr(std::is_same_v<ADataTypeBuf, pk_int4_t>)
            {
                const fp32x2_t fp32_val = pk_int4_t_to_fp32x2_t(A[a_index / packed_size_a]);
                if(k % 2 == 1)
                    v_a = fp32_val.hi;
                else
                    v_a = fp32_val.lo;
            }
            else if constexpr(std::is_same_v<ADataTypeBuf, pk_fp4_t>)
            {
                const fp32x2_t fp32_val = pk_fp4_to_fp32x2(A[a_index / packed_size_a], 1.0f);
                if(k % 2 == 1)
                    v_a = fp32_val.hi;
                else
                    v_a = fp32_val.lo;
            }
            else
            {
                v_a = ck_tile::type_convert<AccDataType>(A[a_index]);
            }
            if constexpr(std::is_same_v<BDataTypeBuf, pk_int4_t>)
            {
                const fp32x2_t fp32_val = pk_int4_t_to_fp32x2_t(B[b_index / packed_size_b]);
                if(k % 2 == 1)
                    v_b = fp32_val.hi;
                else
                    v_b = fp32_val.lo;
            }
            else if constexpr(std::is_same_v<BDataTypeBuf, pk_fp4_t>)
            {
                const fp32x2_t fp32_val = pk_fp4_to_fp32x2(B[b_index / packed_size_b], 1.0f);
                if(k % 2 == 1)
                    v_b = fp32_val.hi;
                else
                    v_b = fp32_val.lo;
            }
            else
            {
                v_b = ck_tile::type_convert<AccDataType>(B[b_index]);
            }

            if constexpr(std::is_same_v<ADataTypeCompute, tf32_t>)
            {
#ifdef CK_GFX950_SUPPORT
                // gfx950: use 3x bf16 emulation
                bf16_t v_a_bf16_big = ck_tile::type_convert<bf16_t>(v_a);
                bf16_t v_a_bf16_small =
                    ck_tile::type_convert<bf16_t>(v_a - type_convert<AccDataType>(v_a_bf16_big));
                bf16_t v_b_bf16_big = ck_tile::type_convert<bf16_t>(v_b);
                bf16_t v_b_bf16_small =
                    ck_tile::type_convert<bf16_t>(v_b - type_convert<AccDataType>(v_b_bf16_big));

                acc += ck_tile::type_convert<AccDataType>(v_a_bf16_big) *
                           ck_tile::type_convert<AccDataType>(v_b_bf16_small) +
                       ck_tile::type_convert<AccDataType>(v_a_bf16_small) *
                           ck_tile::type_convert<AccDataType>(v_b_bf16_big) +
                       ck_tile::type_convert<AccDataType>(v_a_bf16_big) *
                           ck_tile::type_convert<AccDataType>(v_b_bf16_big);
#else
                // Other architectures: use fp32 fallback
                acc += v_a * v_b;
#endif
            }
            else
            {
                acc += v_a * v_b;
            }
        }

        int c_index = (std::is_same_v<LayoutC, tensor_layout::gemm::RowMajor>)
                          ? row * strideC + col
                          : col * strideC + row;
        C[c_index]  = ck_tile::type_convert<CDataType>(acc);
    }
}

template <typename ADataType_,
          typename BDataType_,
          typename AccDataType,
          typename CDataType,
          typename LayoutA,
          typename LayoutB,
          typename LayoutC>
__global__ void blockwise_gemm_kernel(if_select_t<ADataType_, tf32_t, float, ADataType_>* A,
                                      if_select_t<BDataType_, tf32_t, float, BDataType_>* B,
                                      CDataType* C,
                                      ck_tile::index_t M,
                                      ck_tile::index_t N,
                                      ck_tile::index_t K,
                                      ck_tile::index_t strideA,
                                      ck_tile::index_t strideB,
                                      ck_tile::index_t strideC,
                                      ck_tile::index_t scale_granularity_m,
                                      ck_tile::index_t scale_granularity_n,
                                      ck_tile::index_t scale_granularity_k,
                                      float* scale_A_ptr,
                                      float* scale_B_ptr)
{
    if constexpr(std::is_same_v<ADataType_, tf32_t> || std::is_same_v<BDataType_, tf32_t>)
        static_assert(std::is_same_v<ADataType_, BDataType_>,
                      "ADataType and BDataType must be the same");
    using ADataTypeCompute = ADataType_;
    // ADataTypeBuf: buffer/storage type (fp32 when tf32)
    using ADataTypeBuf = if_select_t<ADataType_, tf32_t, float, ADataType_>;
    using BDataTypeBuf = if_select_t<BDataType_, tf32_t, float, BDataType_>;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int row = idx / N; // Compute row index
    int col = idx % N; // Compute column index

    if(row < M && col < N)
    {
        AccDataType acc = 0.0, acc_temp = 0.0;

        index_t scale_A_stride = (M + scale_granularity_m - 1) / scale_granularity_m;
        index_t scale_B_stride = (N + scale_granularity_n - 1) / scale_granularity_n;

        float scale_A = 0;
        float scale_B = 0;

        for(int k = 0; k < K; ++k)
        {
            if(k % scale_granularity_k == 0)
            {
                // update acc
                acc += acc_temp * scale_A * scale_B;
                acc_temp = 0.0;
                // update scale factors
                scale_A = scale_A_ptr[(row / scale_granularity_m) +
                                      (k / scale_granularity_k) * scale_A_stride];
                scale_B = scale_B_ptr[(col / scale_granularity_n) +
                                      (k / scale_granularity_k) * scale_B_stride];
            }

            constexpr index_t packed_size_a = ck_tile::numeric_traits<ADataTypeBuf>::PackedSize;
            constexpr index_t packed_size_b = ck_tile::numeric_traits<BDataTypeBuf>::PackedSize;
            // Adjust indexing based on matrix layout
            int a_index = (std::is_same_v<LayoutA, tensor_layout::gemm::RowMajor>)
                              ? row * strideA + k
                              : k * strideA + row;
            int b_index = (std::is_same_v<LayoutB, tensor_layout::gemm::ColumnMajor>)
                              ? col * strideB + k
                              : k * strideB + col;

            AccDataType v_a;
            AccDataType v_b;
            if constexpr(std::is_same_v<ADataTypeBuf, pk_int4_t>)
            {
                const fp32x2_t fp32_val = pk_int4_t_to_fp32x2_t(A[a_index / packed_size_a]);
                if(k % 2 == 1)
                    v_a = fp32_val.hi;
                else
                    v_a = fp32_val.lo;
            }
            else if constexpr(std::is_same_v<ADataTypeBuf, pk_fp4_t>)
            {
                const fp32x2_t fp32_val = pk_fp4_to_fp32x2(A[a_index / packed_size_a], 1.0f);
                if(k % 2 == 1)
                    v_a = fp32_val.hi;
                else
                    v_a = fp32_val.lo;
            }
            else
            {
                v_a = ck_tile::type_convert<AccDataType>(A[a_index]);
            }

            if constexpr(std::is_same_v<BDataTypeBuf, pk_int4_t>)
            {
                const fp32x2_t fp32_val = pk_int4_t_to_fp32x2_t(B[b_index / packed_size_b]);
                if(k % 2 == 1)
                    v_b = fp32_val.hi;
                else
                    v_b = fp32_val.lo;
            }
            else if constexpr(std::is_same_v<BDataTypeBuf, pk_fp4_t>)
            {
                const fp32x2_t fp32_val = pk_fp4_to_fp32x2(B[b_index / packed_size_b], 1.0f);
                if(k % 2 == 1)
                    v_b = fp32_val.hi;
                else
                    v_b = fp32_val.lo;
            }
            else
            {
                v_b = ck_tile::type_convert<AccDataType>(B[b_index]);
            }

            if constexpr(std::is_same_v<ADataTypeCompute, tf32_t>)
            {
#ifdef CK_GFX950_SUPPORT
                // gfx950: use 3x bf16 emulation
                bf16_t v_a_bf16_big = ck_tile::type_convert<bf16_t>(v_a);
                bf16_t v_a_bf16_small =
                    ck_tile::type_convert<bf16_t>(v_a - type_convert<AccDataType>(v_a_bf16_big));
                bf16_t v_b_bf16_big = ck_tile::type_convert<bf16_t>(v_b);
                bf16_t v_b_bf16_small =
                    ck_tile::type_convert<bf16_t>(v_b - type_convert<AccDataType>(v_b_bf16_big));

                acc_temp += ck_tile::type_convert<AccDataType>(v_a_bf16_big) *
                                ck_tile::type_convert<AccDataType>(v_b_bf16_small) +
                            ck_tile::type_convert<AccDataType>(v_a_bf16_small) *
                                ck_tile::type_convert<AccDataType>(v_b_bf16_big) +
                            ck_tile::type_convert<AccDataType>(v_a_bf16_big) *
                                ck_tile::type_convert<AccDataType>(v_b_bf16_big);
#else
                // Other architectures: use fp32 fallback
                acc_temp += v_a * v_b;
#endif
            }
            else
            {
                acc_temp += v_a * v_b;
            }
        }
        // final accumulation
        acc += acc_temp * scale_A * scale_B;

        int c_index = (std::is_same_v<LayoutC, tensor_layout::gemm::RowMajor>)
                          ? row * strideC + col
                          : col * strideC + row;
        C[c_index]  = ck_tile::type_convert<CDataType>(acc);
    }
}

template <typename ADataType,
          typename BDataType,
          typename AccDataType,
          typename CDataType,
          typename LayoutA,
          typename LayoutB,
          typename LayoutC,
          int MoeGemmKind = 0, // 0: gemm1_gate_only, 1: gemm1_gate_up, 2: gemm2, 3:gemm1_split_k
          typename ActivationOp = identity>
__global__ void moe_gemm_kernel(const ck_tile::index_t* p_sorted_token_ids_,
                                const ck_tile::index_t* p_sorted_expert_ids_,
                                const ck_tile::index_t* p_max_token_id_,
                                const ADataType* A,
                                const BDataType* B,
                                CDataType* C,
                                const AccDataType* expert_weight_ptr,
                                ck_tile::index_t Num_tokens,
                                ck_tile::index_t TokensPerBlock,
                                ck_tile::index_t TopK,
                                ck_tile::index_t M,
                                ck_tile::index_t N,
                                ck_tile::index_t K,
                                ck_tile::index_t strideA,
                                ck_tile::index_t strideB,
                                ck_tile::index_t strideC,
                                index_t scale_granularity_m,
                                index_t scale_granularity_n,
                                index_t scale_granularity_k,
                                float* scale_A_ptr,
                                float* scale_B_ptr,
                                float* expert_bias_ptr)
{
    constexpr auto is_split_k = MoeGemmKind == 3;
    int idx                   = blockIdx.x * blockDim.x + threadIdx.x;
    int problem_N             = MoeGemmKind == 1 ? N / 2 : N;
    int row                   = idx / problem_N; // Compute row index
    int col                   = idx % problem_N; // Compute column index

    index_t gather_token_id  = 0;
    index_t scatter_token_id = 0;
    index_t expert_id        = 0;

    if(row < p_max_token_id_[0])
    {
        expert_id        = p_sorted_expert_ids_[row / TokensPerBlock];
        gather_token_id  = p_sorted_token_ids_[row] & 0xff'ffff;
        scatter_token_id = p_sorted_token_ids_[row] & 0xff'ffff;
        if(gather_token_id >= Num_tokens)
        {
            return;
        }
        if(MoeGemmKind == 2)
        {
            gather_token_id = gather_token_id * TopK + (p_sorted_token_ids_[row] >> 24);
        }
        else
        {
            scatter_token_id = scatter_token_id * TopK + (p_sorted_token_ids_[row] >> 24);
        }
    }
    else
    {
        return;
    }

    if(row < M)
    {
        AccDataType acc    = 0.0;
        AccDataType acc_up = 0.0;

        AccDataType acc_temp    = 0.0;
        AccDataType acc_up_temp = 0.0;

        float scale_A    = 0;
        float scale_B    = 0;
        float scale_B_up = 0;

        index_t scale_A_stride        = (M + scale_granularity_m - 1) / scale_granularity_m;
        index_t scale_B_stride        = (N + scale_granularity_n - 1) / scale_granularity_n;
        index_t scale_B_expert_stride = scale_B_stride * K / scale_granularity_k;

        for(int k = 0; k < K; ++k)
        {
            if(k % scale_granularity_k == 0)
            {
                // update acc
                acc += acc_temp * scale_A * scale_B;
                acc_up += acc_up_temp * scale_A * scale_B_up;
                // reset acc temp
                acc_temp    = 0.0;
                acc_up_temp = 0.0;
                // update scale factors
                scale_A = scale_A_ptr[(gather_token_id / scale_granularity_m) +
                                      (k / scale_granularity_k) * scale_A_stride];
                scale_B =
                    scale_B_ptr[expert_id * scale_B_expert_stride + col / scale_granularity_n +
                                (k / scale_granularity_k) * scale_B_stride];
                if constexpr(MoeGemmKind == 1)
                    scale_B_up = scale_B_ptr[expert_id * scale_B_expert_stride +
                                             (col + problem_N) / scale_granularity_n +
                                             (k / scale_granularity_k) * scale_B_stride];
            }

            constexpr index_t packed_size_a = ck_tile::numeric_traits<ADataType>::PackedSize;
            constexpr index_t packed_size_b = ck_tile::numeric_traits<BDataType>::PackedSize;
            // Adjust indexing based on matrix layout
            int a_index = (std::is_same_v<LayoutA, tensor_layout::gemm::RowMajor>)
                              ? gather_token_id * strideA + k
                              : k * strideA + gather_token_id;

            long b_index =
                long(expert_id) * N * K +
                ((std::is_same_v<LayoutB, tensor_layout::gemm::ColumnMajor>) ? col * strideB + k
                                                                             : k * strideB + col);
            long b_index_up;
            if constexpr(MoeGemmKind == 1)
                b_index_up = long(expert_id) * N * K +
                             ((std::is_same_v<LayoutB, tensor_layout::gemm::ColumnMajor>)
                                  ? (col + problem_N) * strideB + k
                                  : k * strideB + col + problem_N);

            AccDataType v_a;
            AccDataType v_b;
            AccDataType v_b_up;
            if constexpr(std::is_same_v<ADataType, pk_int4_t>)
            {
                const fp32x2_t fp32_val = pk_int4_t_to_fp32x2_t(A[a_index / packed_size_a]);
                if(k % 2 == 1)
                    v_a = fp32_val.hi;
                else
                    v_a = fp32_val.lo;
            }
            else if constexpr(std::is_same_v<ADataType, pk_fp4_t>)
            {
                const fp32x2_t fp32_val = pk_fp4_to_fp32x2(A[a_index / packed_size_a]);
                if(k % 2 == 1)
                    v_a = fp32_val.hi;
                else
                    v_a = fp32_val.lo;
            }
            else
            {
                v_a = ck_tile::type_convert<AccDataType>(A[a_index]);
            }
            if constexpr(std::is_same_v<BDataType, pk_int4_t>)
            {
                const fp32x2_t fp32_val = pk_int4_t_to_fp32x2_t(B[b_index / packed_size_b]);
                if(k % 2 == 1)
                    v_b = fp32_val.hi;
                else
                    v_b = fp32_val.lo;
                if constexpr(MoeGemmKind == 1)
                {
                    const fp32x2_t fp32_val_up =
                        pk_int4_t_to_fp32x2_t(B[b_index_up / packed_size_b]);
                    if(k % 2 == 1)
                        v_b_up = fp32_val_up.hi;
                    else
                        v_b_up = fp32_val_up.lo;
                }
            }
            else if constexpr(std::is_same_v<BDataType, pk_fp4_t>)
            {
                const fp32x2_t fp32_val = pk_fp4_to_fp32x2(B[b_index / packed_size_b], 1.0f);
                if(k % 2 == 1)
                    v_b = fp32_val.hi;
                else
                    v_b = fp32_val.lo;
                if constexpr(MoeGemmKind == 1)
                {
                    const fp32x2_t fp32_val_up =
                        pk_fp4_to_fp32x2(B[b_index_up / packed_size_b], 1.0f);
                    if(k % 2 == 1)
                        v_b_up = fp32_val_up.hi;
                    else
                        v_b_up = fp32_val_up.lo;
                }
            }
            else
            {
                v_b = ck_tile::type_convert<AccDataType>(B[b_index]);
                if constexpr(MoeGemmKind == 1)
                    v_b_up = ck_tile::type_convert<AccDataType>(B[b_index_up]);
            }
            acc_temp += v_a * v_b;
            if constexpr(MoeGemmKind == 1)
                acc_up_temp += v_a * v_b_up;
        }

        acc += acc_temp * scale_A * scale_B;
        acc_up += acc_up_temp * scale_A * scale_B_up;

        float bias = 0.f, bias_up = 0.f;
        if(expert_bias_ptr != nullptr && !is_split_k)
        {
            bias = expert_bias_ptr[expert_id * N + col];
            if constexpr(MoeGemmKind == 1)
                bias_up = expert_bias_ptr[expert_id * N + col + problem_N];
        }

        int c_index = (std::is_same_v<LayoutC, tensor_layout::gemm::RowMajor>)
                          ? scatter_token_id * strideC + col
                          : col * strideC + scatter_token_id;
        if constexpr(MoeGemmKind < 2)
        {
            C[c_index] = ck_tile::type_convert<CDataType>(
                ActivationOp{}(acc + bias, MoeGemmKind == 1 ? acc_up + bias_up : 1));
        }
        else
        {
            // moe gemm2 don't use activation.
            auto weight =
                is_split_k ? ck_tile::type_convert<AccDataType>(1.0f) : expert_weight_ptr[row];
            CDataType res = ck_tile::type_convert<CDataType>((acc + bias) * weight);

            thread_buffer<CDataType, 2> add_v = 0;
            if(c_index % 2)
            {
                // result is the second value of fp16 pair.
                add_v.template get_as<CDataType>()[1] = res;
            }
            else
            {
                // result is the first value of fp16 pair.
                add_v.template get_as<CDataType>()[0] = res;
            }
            // mask last bit to make sure atomicAdd pointer is aligned of DWORD.
            atomic_add_g<CDataType, 2>(reinterpret_cast<CDataType*>(C + (c_index & 0xffff'fffe)),
                                       add_v);
        }
    }
}

