template <bool HasMainLoop,
              TailNumber TailNum,
              typename AGridDesc,
              typename ABlockDesc,
              typename ABlockTransfer,
              typename AGridBuffer,
              typename ABlockBuffer,
              typename ABlockTransferStep,
              typename BGridDesc,
              typename BBlockTransfer,
              typename BGridBuffer,
              typename BBlockBuffer,
              typename BBlockTransferStep,
              typename CThreadBuffer>
    __device__ void Run(const AGridDesc& a_grid_desc,
                        const ABlockDesc& a_block_desc,
                        ABlockTransfer& a_blockwise_copy,
                        const AGridBuffer& a_grid_buf,
                        ABlockBuffer& a_block_buf,
                        const ABlockTransferStep& a_block_copy_step,
                        const BGridDesc& b_grid_desc,
                        BBlockTransfer& b_blockwise_copy,
                        const BGridBuffer& b_grid_buf,
                        BBlockBuffer& b_block_buf,
                        const BBlockTransferStep& b_block_copy_step,
                        CThreadBuffer& c_thread_buf,
                        index_t num_loop) const
    {
        ignore = b_block_buf;
        __builtin_amdgcn_sched_barrier(0);
        auto a_thread_buf = make_static_buffer<AddressSpaceEnum::Vgpr, ComputeDataType>(
            a_thread_desc_.GetElementSpaceSize());
        auto b_thread_buf = make_static_buffer<AddressSpaceEnum::Vgpr, ComputeDataType>(
            b_thread_desc_.GetElementSpaceSize());

        StaticallyIndexedArray<decltype(b_thread_buf), Number<2>{}> b_thread_bufs;
        constexpr auto b_block_origin_idx = make_tuple(I0, I0, I0, I0);

        // Global prefetch A1 B1
        a_blockwise_copy.RunRead(a_grid_desc, a_grid_buf, I0);
        b_blockwise_copy.Run(b_grid_desc,
                             b_grid_buf,
                             b_block_desc_n0_n1_k0_k1,
                             b_block_origin_idx,
                             b_thread_bufs(I0));

        a_blockwise_copy.MoveSrcSliceWindow(a_grid_desc, a_block_copy_step);
        b_blockwise_copy.MoveSrcSliceWindow(b_grid_desc, b_block_copy_step);
        __builtin_amdgcn_sched_barrier(0);

        // Local prefill A1
        a_blockwise_copy.RunWrite(a_block_desc, a_block_buf, I0);

        // Global prefetch A2
        a_blockwise_copy.RunRead(a_grid_desc, a_grid_buf, I0);
        a_blockwise_copy.MoveSrcSliceWindow(a_grid_desc, a_block_copy_step);

        // Local prefetch A1
        block_sync_lds();
        static_ford<Sequence<MRepeat, KRepeat, KGroup>>{}([&](auto mkg) {
            constexpr auto m0  = Number<mkg[Number<0>{}]>{};
            constexpr auto k0  = Number<mkg[Number<1>{}]>{};
            constexpr auto kg0 = Number<mkg[Number<2>{}]>{};
            a_thread_copy_.Run(a_block_desc_m0_m1_m2_k0_k1_k2,
                               make_tuple(m0, I0, I0, Number<k0 * KGroup + kg0>{}, I0, I0),
                               a_block_buf,
                               a_thread_desc_,
                               make_tuple(m0, I0, I0, k0, I0, Number<kg0 * A_K1>{}),
                               a_thread_buf);
        });

        // Initialize C
        c_thread_buf.Clear();

        __builtin_amdgcn_sched_barrier(0);

        // main body
        if constexpr(HasMainLoop)
        {
            index_t i = 0;
            do
            {
                auto LoopFunc = [&](auto mfma_reg_buf, auto local_read_buf) {
                    b_blockwise_copy.Run(b_grid_desc,
                                         b_grid_buf,
                                         b_block_desc_n0_n1_k0_k1,
                                         b_block_origin_idx,
                                         b_thread_bufs(local_read_buf));
                    b_blockwise_copy.MoveSrcSliceWindow(b_grid_desc, b_block_copy_step);

                    block_sync_lds();
                    a_blockwise_copy.RunWrite(a_block_desc, a_block_buf, mfma_reg_buf);

                    a_blockwise_copy.RunRead(a_grid_desc, a_grid_buf, local_read_buf);
                    a_blockwise_copy.MoveSrcSliceWindow(a_grid_desc, a_block_copy_step);

                    static_ford<Sequence<MRepeat, NRepeat, KRepeat>>{}([&](auto mnk) {
                        constexpr auto m0 = Number<mnk[Number<0>{}]>{};
                        constexpr auto n0 = Number<mnk[Number<1>{}]>{};
                        constexpr auto k0 = Number<mnk[Number<2>{}]>{};
                        vector_type<ComputeDataType, KPack> a_thread_vec;
                        vector_type<ComputeDataType, KPack> b_thread_vec;

                        static_for<0, KPack, 1>{}([&](auto ik) {
                            a_thread_vec.template AsType<ComputeDataType>()(ik) =
                                a_thread_buf[Number<a_thread_desc_.CalculateOffset(
                                    make_tuple(m0, I0, I0, k0, I0, ik))>{}];
                            b_thread_vec.template AsType<ComputeDataType>()(ik) =
                                b_thread_bufs[mfma_reg_buf][Number<b_thread_desc_.CalculateOffset(
                                    make_tuple(n0, I0, k0, ik))>{}];
                        });
                        using mfma_input_type =
                            typename vector_type<ComputeDataType, xdlops_gemm.K1PerXdlops>::type;

                        constexpr index_t c_offset =
                            c_thread_desc_.CalculateOffset(make_tuple(m0, n0, 0));

                        xdlops_gemm.Run(a_thread_vec.template AsType<mfma_input_type>(),
                                        b_thread_vec.template AsType<mfma_input_type>(),
                                        c_thread_buf.GetVectorTypeReference(Number<c_offset>{}));
                    });

                    block_sync_lds();

                    // loop prefetch copy
                    static_ford<Sequence<MRepeat, KRepeat, KGroup>>{}([&](auto mkg) {
                        constexpr auto m0  = Number<mkg[Number<0>{}]>{};
                        constexpr auto k0  = Number<mkg[Number<1>{}]>{};
                        constexpr auto kg0 = Number<mkg[Number<2>{}]>{};
                        a_thread_copy_.Run(
                            a_block_desc_m0_m1_m2_k0_k1_k2,
                            make_tuple(m0, I0, I0, Number<k0 * KGroup + kg0>{}, I0, I0),
                            a_block_buf,
                            a_thread_desc_,
                            make_tuple(m0, I0, I0, k0, I0, Number<kg0 * A_K1>{}),
                            a_thread_buf);
                    });

                    HotLoopScheduler();
                    __builtin_amdgcn_sched_barrier(0);
                };

                LoopFunc(I0, I1);
                LoopFunc(I1, I0);

                i += 2;
            } while(i < (num_loop - 2));
        }
        // tail
        if constexpr(TailNum == TailNumber::Even)
        {
            b_blockwise_copy.Run(b_grid_desc,
                                 b_grid_buf,
                                 b_block_desc_n0_n1_k0_k1,
                                 b_block_origin_idx,
                                 b_thread_bufs(I1));

            block_sync_lds();
            a_blockwise_copy.RunWrite(a_block_desc, a_block_buf);

            static_ford<Sequence<MRepeat, NRepeat, KRepeat>>{}([&](auto mnk) {
                constexpr auto m0 = Number<mnk[Number<0>{}]>{};
                constexpr auto n0 = Number<mnk[Number<1>{}]>{};
                constexpr auto k0 = Number<mnk[Number<2>{}]>{};
                vector_type<ComputeDataType, KPack> a_thread_vec;
                vector_type<ComputeDataType, KPack> b_thread_vec;

                static_for<0, KPack, 1>{}([&](auto ik) {
                    a_thread_vec.template AsType<ComputeDataType>()(ik) =
                        a_thread_buf[Number<a_thread_desc_.CalculateOffset(
                            make_tuple(m0, I0, I0, k0, I0, ik))>{}];
                    b_thread_vec.template AsType<ComputeDataType>()(ik) = b_thread_bufs
                        [I0][Number<b_thread_desc_.CalculateOffset(make_tuple(n0, I0, k0, ik))>{}];
                });

                using mfma_input_type =
                    typename vector_type<ComputeDataType, xdlops_gemm.K1PerXdlops>::type;

                constexpr index_t c_offset = c_thread_desc_.CalculateOffset(make_tuple(m0, n0, 0));

                xdlops_gemm.Run(a_thread_vec.template AsType<mfma_input_type>(),
                                b_thread_vec.template AsType<mfma_input_type>(),
                                c_thread_buf.GetVectorTypeReference(Number<c_offset>{}));
            });

            block_sync_lds();

            // tail Local Prefetch A1
            static_ford<Sequence<MRepeat, KRepeat, KGroup>>{}([&](auto mkg) {
                constexpr auto m0  = Number<mkg[Number<0>{}]>{};
                constexpr auto k0  = Number<mkg[Number<1>{}]>{};
                constexpr auto kg0 = Number<mkg[Number<2>{}]>{};
                a_thread_copy_.Run(a_block_desc_m0_m1_m2_k0_k1_k2,
                                   make_tuple(m0, I0, I0, Number<k0 * KGroup + kg0>{}, I0, I0),
                                   a_block_buf,
                                   a_thread_desc_,
                                   make_tuple(m0, I0, I0, k0, I0, Number<kg0 * A_K1>{}),
                                   a_thread_buf);
            });

            __builtin_amdgcn_sched_barrier(0);

            static_ford<Sequence<MRepeat, NRepeat, KRepeat>>{}([&](auto mnk) {
                constexpr auto m0 = Number<mnk[Number<0>{}]>{};
                constexpr auto n0 = Number<mnk[Number<1>{}]>{};
                constexpr auto k0 = Number<mnk[Number<2>{}]>{};
                vector_type<ComputeDataType, KPack> a_thread_vec;
                vector_type<ComputeDataType, KPack> b_thread_vec;

                static_for<0, KPack, 1>{}([&](auto ik) {
                    a_thread_vec.template AsType<ComputeDataType>()(ik) =
                        a_thread_buf[Number<a_thread_desc_.CalculateOffset(
                            make_tuple(m0, I0, I0, k0, I0, ik))>{}];
                    b_thread_vec.template AsType<ComputeDataType>()(ik) = b_thread_bufs
                        [I1][Number<b_thread_desc_.CalculateOffset(make_tuple(n0, I0, k0, ik))>{}];
                });

                using mfma_input_type =
                    typename vector_type<ComputeDataType, xdlops_gemm.K1PerXdlops>::type;

                constexpr index_t c_offset = c_thread_desc_.CalculateOffset(make_tuple(m0, n0, 0));

                xdlops_gemm.Run(a_thread_vec.template AsType<mfma_input_type>(),
                                b_thread_vec.template AsType<mfma_input_type>(),
                                c_thread_buf.GetVectorTypeReference(Number<c_offset>{}));
            });
            // Let's leak last MFMA block to epilogue region, cover the potential lds-shuffle
            // latency
            // __builtin_amdgcn_sched_barrier(0);
        }
        else if constexpr(TailNum == TailNumber::Odd)
        {
            static_ford<Sequence<MRepeat, NRepeat, KRepeat>>{}([&](auto mnk) {
                constexpr auto m0 = Number<mnk[Number<0>{}]>{};
                constexpr auto n0 = Number<mnk[Number<1>{}]>{};
                constexpr auto k0 = Number<mnk[Number<2>{}]>{};
                vector_type<ComputeDataType, KPack> a_thread_vec;
                vector_type<ComputeDataType, KPack> b_thread_vec;

                static_for<0, KPack, 1>{}([&](auto ik) {
                    a_thread_vec.template AsType<ComputeDataType>()(ik) =
                        a_thread_buf[Number<a_thread_desc_.CalculateOffset(
                            make_tuple(m0, I0, I0, k0, I0, ik))>{}];
                    b_thread_vec.template AsType<ComputeDataType>()(ik) = b_thread_bufs
                        [I0][Number<b_thread_desc_.CalculateOffset(make_tuple(n0, I0, k0, ik))>{}];
                });

                using mfma_input_type =
                    typename vector_type<ComputeDataType, xdlops_gemm.K1PerXdlops>::type;

                constexpr index_t c_offset = c_thread_desc_.CalculateOffset(make_tuple(m0, n0, 0));

                xdlops_gemm.Run(a_thread_vec.template AsType<mfma_input_type>(),
                                b_thread_vec.template AsType<mfma_input_type>(),
                                c_thread_buf.GetVectorTypeReference(Number<c_offset>{}));
            });
        }
    }

template <typename TileDesc_M0_M1_M2_K>
    __host__ __device__ static constexpr auto MakeAGemmMmaTileDescriptor(const TileDesc_M0_M1_M2_K&)
    {
        constexpr index_t M0 = TileDesc_M0_M1_M2_K{}.GetLength(Number<0>{});
        constexpr index_t M1 = TileDesc_M0_M1_M2_K{}.GetLength(Number<1>{});
        constexpr index_t M2 = TileDesc_M0_M1_M2_K{}.GetLength(Number<2>{});
        constexpr index_t K2 = KPack / KGroup;
        constexpr index_t K1 = WaveSize / NPerXDL;
        constexpr index_t K0 = KRepeat * KGroup;

        return transform_tensor_descriptor(
            TileDesc_M0_M1_M2_K{},
            make_tuple(
                make_pass_through_transform(Number<M0>{}),
                make_pass_through_transform(Number<M1>{}),
                make_pass_through_transform(Number<M2>{}),
                make_unmerge_transform(make_tuple(Number<K0>{}, Number<K1>{}, Number<K2>{}))),
            make_tuple(Sequence<0>{}, Sequence<1>{}, Sequence<2>{}, Sequence<3>{}),
            make_tuple(Sequence<0>{}, Sequence<1>{}, Sequence<2>{}, Sequence<3, 4, 5>{}));
    }

__host__ __device__ static constexpr bool BlockHasHotloop(index_t num_loop)
    {
        return num_loop > PrefetchStages;
    }

__host__ __device__ static constexpr TailNumber BlockLoopTailNum(index_t num_loop)
    {

        return num_loop % 2 == 0 ? TailNumber::Even : TailNumber::Odd;
    }

__device__ static constexpr auto HotLoopScheduler()
    {
        // constexpr auto num_ds_read_inst_a     = HotLoopInstList::A_LDS_Read_Inst_Num;
        constexpr auto num_buffer_load_inst_a = HotLoopInstList::A_Buffer_Load_Inst_Num;
        constexpr auto num_buffer_load_inst_b = HotLoopInstList::B_Buffer_Load_Inst_Num;

        // B global + A local
        static_for<0, num_buffer_load_inst_b / 2, 1>{}([&](auto i) {
            ignore = i;
            __builtin_amdgcn_sched_group_barrier(0x008, 1, 0); // MFMA
            __builtin_amdgcn_sched_group_barrier(0x020, 1, 0); // VMEM read B
            __builtin_amdgcn_sched_group_barrier(0x008, 1, 0); // MFMA
            __builtin_amdgcn_sched_group_barrier(0x100, 1, 0); // DS read   A
        });

        static_for<0, num_buffer_load_inst_b / 2, 1>{}([&](auto i) {
            ignore = i;
            __builtin_amdgcn_sched_group_barrier(0x008, 1, 0); // MFMA
            __builtin_amdgcn_sched_group_barrier(0x020, 1, 0); // VMEM read B
            __builtin_amdgcn_sched_group_barrier(0x100, 1, 0); // DS read   A
        });

        // A global
        static_for<0, num_buffer_load_inst_a, 1>{}([&](auto i) {
            ignore = i;
            __builtin_amdgcn_sched_group_barrier(0x008, 1, 0); // MFMA
            __builtin_amdgcn_sched_group_barrier(0x200, 1, 0); // DS write
            __builtin_amdgcn_sched_group_barrier(0x008, 1, 0); // MFMA
            __builtin_amdgcn_sched_group_barrier(0x020, 1, 0); // VMEM read
        });

        // A local
        // static_for<0, num_ds_read_inst_a / 2, 1>{}([&](auto i) {
        //     ignore = i;
        //     __builtin_amdgcn_sched_group_barrier(0x008, 1, 0); // MFMA
        //     __builtin_amdgcn_sched_group_barrier(0x100, 2, 0); // DS read
        // });
    }

template <bool HasMainLoop,
              TailNumber TailNum,
              typename AGridDesc,
              typename ABlockDesc,
              typename ABlockTransfer,
              typename AGridBuffer,
              typename ABlockBuffer,
              typename ABlockTransferStep,
              typename BGridDesc,
              typename BBlockTransfer,
              typename BGridBuffer,
              typename BBlockBuffer,
              typename BBlockTransferStep,
              typename CThreadBuffer>
    __device__ void Run(const AGridDesc& a_grid_desc,
                        const ABlockDesc& a_block_desc,
                        ABlockTransfer& a_blockwise_copy,
                        const AGridBuffer& a_grid_buf,
                        ABlockBuffer& a_block_buf,
                        const ABlockTransferStep& a_block_copy_step,
                        const BGridDesc& b_grid_desc,
                        BBlockTransfer& b_blockwise_copy,
                        const BGridBuffer& b_grid_buf,
                        BBlockBuffer& b_block_buf,
                        const BBlockTransferStep& b_block_copy_step,
                        CThreadBuffer& c_thread_buf,
                        index_t num_loop) const
    {
        ignore = b_block_buf;
        __builtin_amdgcn_sched_barrier(0);
        auto a_thread_buf = make_static_buffer<AddressSpaceEnum::Vgpr, ComputeDataType>(
            a_thread_desc_.GetElementSpaceSize());
        auto b_thread_buf = make_static_buffer<AddressSpaceEnum::Vgpr, ComputeDataType>(
            b_thread_desc_.GetElementSpaceSize());

        StaticallyIndexedArray<decltype(a_thread_buf), Number<2>{}> a_thread_bufs;
        StaticallyIndexedArray<decltype(b_thread_buf), Number<2>{}> b_thread_bufs;
        constexpr auto b_block_origin_idx = make_tuple(I0, I0, I0, I0);

        // Global prefetch A1, B1
        a_blockwise_copy.RunRead(a_grid_desc, a_grid_buf, I0);
        b_blockwise_copy.Run(b_grid_desc,
                             b_grid_buf,
                             b_block_desc_n0_n1_k0_k1,
                             b_block_origin_idx,
                             b_thread_bufs(I0));

        a_blockwise_copy.MoveSrcSliceWindow(a_grid_desc, a_block_copy_step);
        b_blockwise_copy.MoveSrcSliceWindow(b_grid_desc, b_block_copy_step);

        // Local prefill A1
        a_blockwise_copy.RunWrite(a_block_desc, a_block_buf.At(I0), I0);

        // Global prefetch A2
        a_blockwise_copy.RunRead(a_grid_desc, a_grid_buf, I1);
        a_blockwise_copy.MoveSrcSliceWindow(a_grid_desc, a_block_copy_step);

        // Local prefetch A1
        block_sync_lds();
        static_ford<Sequence<MRepeat, KRepeat, KGroup>>{}([&](auto mkg) {
            constexpr auto m0  = Number<mkg[Number<0>{}]>{};
            constexpr auto k0  = Number<mkg[Number<1>{}]>{};
            constexpr auto kg0 = Number<mkg[Number<2>{}]>{};
            a_thread_copy_.Run(a_block_desc_m0_m1_m2_k0_k1_k2,
                               make_tuple(m0, I0, I0, Number<k0 * KGroup + kg0>{}, I0, I0),
                               a_block_buf.At(I0),
                               a_thread_desc_,
                               make_tuple(m0, I0, I0, k0, I0, Number<kg0 * A_K1>{}),
                               a_thread_bufs(I0));
        });

        // Local prefill A2
        a_blockwise_copy.RunWrite(a_block_desc, a_block_buf.At(I1), I1);

        // // Global prefetch A3
        a_blockwise_copy.RunRead(a_grid_desc, a_grid_buf, I0);
        a_blockwise_copy.MoveSrcSliceWindow(a_grid_desc, a_block_copy_step);

        // Initialize C
        c_thread_buf.Clear();

        __builtin_amdgcn_sched_barrier(0);

        // main body
        if constexpr(HasMainLoop)
        {
            index_t i = 0;
            do
            {
                auto LoopFunc = [&](auto mfma_reg_buf, auto local_read_buf) {
                    block_sync_lds();

                    b_blockwise_copy.Run(b_grid_desc,
                                         b_grid_buf,
                                         b_block_desc_n0_n1_k0_k1,
                                         b_block_origin_idx,
                                         b_thread_bufs(local_read_buf));
                    b_blockwise_copy.MoveSrcSliceWindow(b_grid_desc, b_block_copy_step);

                    // main loop A matrix prefetch
                    static_ford<Sequence<MRepeat, KRepeat, KGroup>>{}([&](auto mkg) {
                        constexpr auto m0  = Number<mkg[Number<0>{}]>{};
                        constexpr auto k0  = Number<mkg[Number<1>{}]>{};
                        constexpr auto kg0 = Number<mkg[Number<2>{}]>{};
                        a_thread_copy_.Run(
                            a_block_desc_m0_m1_m2_k0_k1_k2,
                            make_tuple(m0, I0, I0, Number<k0 * KGroup + kg0>{}, I0, I0),
                            a_block_buf.At(local_read_buf),
                            a_thread_desc_,
                            make_tuple(m0, I0, I0, k0, I0, Number<kg0 * A_K1>{}),
                            a_thread_bufs(local_read_buf));
                    });

                    a_blockwise_copy.RunWrite(
                        a_block_desc, a_block_buf.At(mfma_reg_buf), mfma_reg_buf);

                    a_blockwise_copy.RunRead(a_grid_desc, a_grid_buf, local_read_buf);
                    a_blockwise_copy.MoveSrcSliceWindow(a_grid_desc, a_block_copy_step);

                    static_ford<Sequence<MRepeat, NRepeat, KRepeat>>{}([&](auto mnk) {
                        constexpr auto m0 = Number<mnk[Number<0>{}]>{};
                        constexpr auto n0 = Number<mnk[Number<1>{}]>{};
                        constexpr auto k0 = Number<mnk[Number<2>{}]>{};
                        vector_type<ComputeDataType, KPack> a_thread_vec;
                        vector_type<ComputeDataType, KPack> b_thread_vec;

                        static_for<0, KPack, 1>{}([&](auto ik) {
                            a_thread_vec.template AsType<ComputeDataType>()(ik) =
                                a_thread_bufs[mfma_reg_buf][Number<a_thread_desc_.CalculateOffset(
                                    make_tuple(m0, I0, I0, k0, I0, ik))>{}];
                            b_thread_vec.template AsType<ComputeDataType>()(ik) =
                                b_thread_bufs[mfma_reg_buf][Number<b_thread_desc_.CalculateOffset(
                                    make_tuple(n0, I0, k0, ik))>{}];
                        });

                        using mfma_input_type =
                            typename vector_type<ComputeDataType, xdlops_gemm.K1PerXdlops>::type;

                        constexpr index_t c_offset =
                            c_thread_desc_.CalculateOffset(make_tuple(m0, n0, 0));

                        xdlops_gemm.Run(a_thread_vec.template AsType<mfma_input_type>(),
                                        b_thread_vec.template AsType<mfma_input_type>(),
                                        c_thread_buf.GetVectorTypeReference(Number<c_offset>{}));
                    });

                    HotLoopScheduler();
                    __builtin_amdgcn_sched_barrier(0);
                };

                LoopFunc(I0, I1);
                LoopFunc(I1, I0);

                i += 2;
            } while(i < (num_loop - 3));
        }
        // tail

        auto ReadWriteCompFunc = [&](auto mfma_reg, auto local_read_reg) {
            block_sync_lds();

            b_blockwise_copy.Run(b_grid_desc,
                                 b_grid_buf,
                                 b_block_desc_n0_n1_k0_k1,
                                 b_block_origin_idx,
                                 b_thread_bufs(local_read_reg));
            b_blockwise_copy.MoveSrcSliceWindow(b_grid_desc, b_block_copy_step);

            // tail prefetch A
            static_ford<Sequence<MRepeat, KRepeat, KGroup>>{}([&](auto mkg) {
                constexpr auto m0  = Number<mkg[Number<0>{}]>{};
                constexpr auto k0  = Number<mkg[Number<1>{}]>{};
                constexpr auto kg0 = Number<mkg[Number<2>{}]>{};
                a_thread_copy_.Run(a_block_desc_m0_m1_m2_k0_k1_k2,
                                   make_tuple(m0, I0, I0, Number<k0 * KGroup + kg0>{}, I0, I0),
                                   a_block_buf.At(local_read_reg),
                                   a_thread_desc_,
                                   make_tuple(m0, I0, I0, k0, I0, Number<kg0 * A_K1>{}),
                                   a_thread_bufs(local_read_reg));
            });

            a_blockwise_copy.RunWrite(a_block_desc, a_block_buf.At(mfma_reg), mfma_reg);

            static_ford<Sequence<MRepeat, NRepeat, KRepeat>>{}([&](auto mnk) {
                constexpr auto m0 = Number<mnk[Number<0>{}]>{};
                constexpr auto n0 = Number<mnk[Number<1>{}]>{};
                constexpr auto k0 = Number<mnk[Number<2>{}]>{};
                vector_type<ComputeDataType, KPack> a_thread_vec;
                vector_type<ComputeDataType, KPack> b_thread_vec;

                static_for<0, KPack, 1>{}([&](auto ik) {
                    a_thread_vec.template AsType<ComputeDataType>()(ik) =
                        a_thread_bufs[mfma_reg][Number<a_thread_desc_.CalculateOffset(
                            make_tuple(m0, I0, I0, k0, I0, ik))>{}];
                    b_thread_vec.template AsType<ComputeDataType>()(ik) =
                        b_thread_bufs[mfma_reg][Number<b_thread_desc_.CalculateOffset(
                            make_tuple(n0, I0, k0, ik))>{}];
                });

                using mfma_input_type =
                    typename vector_type<ComputeDataType, xdlops_gemm.K1PerXdlops>::type;

                constexpr index_t c_offset = c_thread_desc_.CalculateOffset(make_tuple(m0, n0, 0));

                xdlops_gemm.Run(a_thread_vec.template AsType<mfma_input_type>(),
                                b_thread_vec.template AsType<mfma_input_type>(),
                                c_thread_buf.GetVectorTypeReference(Number<c_offset>{}));
            });

            HotLoopScheduler();
            __builtin_amdgcn_sched_barrier(0);
        };

        auto ReadCompFunc = [&](auto mfma_reg, auto local_read_reg) {
            block_sync_lds();

            b_blockwise_copy.Run(b_grid_desc,
                                 b_grid_buf,
                                 b_block_desc_n0_n1_k0_k1,
                                 b_block_origin_idx,
                                 b_thread_bufs(local_read_reg));

            static_ford<Sequence<MRepeat, KRepeat, KGroup>>{}([&](auto mkg) {
                constexpr auto m0  = Number<mkg[Number<0>{}]>{};
                constexpr auto k0  = Number<mkg[Number<1>{}]>{};
                constexpr auto kg0 = Number<mkg[Number<2>{}]>{};
                a_thread_copy_.Run(a_block_desc_m0_m1_m2_k0_k1_k2,
                                   make_tuple(m0, I0, I0, Number<k0 * KGroup + kg0>{}, I0, I0),
                                   a_block_buf.At(local_read_reg),
                                   a_thread_desc_,
                                   make_tuple(m0, I0, I0, k0, I0, Number<kg0 * A_K1>{}),
                                   a_thread_bufs(local_read_reg));
            });

            static_ford<Sequence<MRepeat, NRepeat, KRepeat>>{}([&](auto mnk) {
                constexpr auto m0 = Number<mnk[Number<0>{}]>{};
                constexpr auto n0 = Number<mnk[Number<1>{}]>{};
                constexpr auto k0 = Number<mnk[Number<2>{}]>{};
                vector_type<ComputeDataType, KPack> a_thread_vec;
                vector_type<ComputeDataType, KPack> b_thread_vec;

                static_for<0, KPack, 1>{}([&](auto ik) {
                    a_thread_vec.template AsType<ComputeDataType>()(ik) =
                        a_thread_bufs[mfma_reg][Number<a_thread_desc_.CalculateOffset(
                            make_tuple(m0, I0, I0, k0, I0, ik))>{}];
                    b_thread_vec.template AsType<ComputeDataType>()(ik) =
                        b_thread_bufs[mfma_reg][Number<b_thread_desc_.CalculateOffset(
                            make_tuple(n0, I0, k0, ik))>{}];
                });

                using mfma_input_type =
                    typename vector_type<ComputeDataType, xdlops_gemm.K1PerXdlops>::type;

                constexpr index_t c_offset = c_thread_desc_.CalculateOffset(make_tuple(m0, n0, 0));

                xdlops_gemm.Run(a_thread_vec.template AsType<mfma_input_type>(),
                                b_thread_vec.template AsType<mfma_input_type>(),
                                c_thread_buf.GetVectorTypeReference(Number<c_offset>{}));
            });

            HotLoopScheduler();
            __builtin_amdgcn_sched_barrier(0);
        };

        auto CompFunc = [&](auto mfma_reg) {
            static_ford<Sequence<MRepeat, NRepeat, KRepeat>>{}([&](auto mnk) {
                constexpr auto m0 = Number<mnk[Number<0>{}]>{};
                constexpr auto n0 = Number<mnk[Number<1>{}]>{};
                constexpr auto k0 = Number<mnk[Number<2>{}]>{};
                vector_type<ComputeDataType, KPack> a_thread_vec;
                vector_type<ComputeDataType, KPack> b_thread_vec;

                static_for<0, KPack, 1>{}([&](auto ik) {
                    a_thread_vec.template AsType<ComputeDataType>()(ik) =
                        a_thread_bufs[mfma_reg][Number<a_thread_desc_.CalculateOffset(
                            make_tuple(m0, I0, I0, k0, I0, ik))>{}];
                    b_thread_vec.template AsType<ComputeDataType>()(ik) =
                        b_thread_bufs[mfma_reg][Number<b_thread_desc_.CalculateOffset(
                            make_tuple(n0, I0, k0, ik))>{}];
                });

                using mfma_input_type =
                    typename vector_type<ComputeDataType, xdlops_gemm.K1PerXdlops>::type;

                constexpr index_t c_offset = c_thread_desc_.CalculateOffset(make_tuple(m0, n0, 0));

                xdlops_gemm.Run(a_thread_vec.template AsType<mfma_input_type>(),
                                b_thread_vec.template AsType<mfma_input_type>(),
                                c_thread_buf.GetVectorTypeReference(Number<c_offset>{}));
            });
        };

        if constexpr(TailNum == TailNumber::Even)
        {
            ReadCompFunc(I0, I1);
            CompFunc(I1);
        }
        else if constexpr(TailNum == TailNumber::Odd)
        {
            ReadWriteCompFunc(I0, I1);
            ReadCompFunc(I1, I0);
            CompFunc(I0);
        }
    }

