                                         ABK1Value,
                                         ABDoTranspose,
                                         GlobalBufferNum>(
            grid_descriptor,
            block_descriptor,
            idx_as_block_begin,
            make_multi_index(wave_idMN / MNRepeatRatio,
                             wave_idK * KRepeat_,
                             (wave_idMN % MNRepeatRatio) * MNRepeat_,
                             lane_group_block,
                             lane_local_id_block),
            ab_element_op);
