                b_element_op,
                cde_element_op,
                a_grid_desc_kbatch_ak0_m_ak1,
                b_grid_desc_kbatch_bk0_n_bk1,
                ds_grid_desc_mblock_mperblock_nblock_nperblock,
                e_grid_desc_mblock_mperblock_nblock_nperblock,
                block_2_etile_map);
        }
