            EGlobalMemoryDataOperation,
            TailNum,
            Block2CTileMap,
            EpilogueArgument,
            BlockMapMBlockIndex,
            BlockMapNBlockIndex>(p_as_grid_splitk,
                                 p_bs_grid_splitk,
