__device__ static void Run(const InGrid1dDesc& in_grid_1d_desc,
                               const InDataType* __restrict__ p_in_global,
                               const IndexDataType* __restrict__ p_indices_global,
                               OutDataType* __restrict__ p_out_global,
                               const ElementwiseOperation& elementwise_op)
    {
        // Global Memory
        const auto in_global_buf = make_dynamic_buffer<AddressSpaceEnum::Global>(
            p_in_global, in_grid_1d_desc.GetElementSpaceSize());

        const auto indices_global_buf =
            make_dynamic_buffer<AddressSpaceEnum::Global>(p_indices_global,
                                                          in_grid_1d_desc.GetElementSpaceSize(),
                                                          NumericLimits<IndexDataType>::Lowest());

        // VGPR
        StaticBuffer<AddressSpaceEnum::Vgpr, InDataType, InVectorSize, true> in_thread_buf;
        StaticBuffer<AddressSpaceEnum::Vgpr, IndexDataType, InVectorSize, true> indices_thread_buf;

        // Thread id, Block id and index
        const index_t thread_global_id  = get_thread_global_1d_id();
        const auto thread_global_offset = make_multi_index(thread_global_id * InVectorSize);
        const index_t blockSize         = get_block_size();
        const index_t blockPerGrid      = get_grid_size();
        const auto M                    = in_grid_1d_desc.GetLength(I0);
        const index_t loop_step         = blockPerGrid * blockSize * InVectorSize;
        const auto loop_step_index      = make_multi_index(loop_step);

        auto in_global_load =
            ThreadwiseTensorSliceTransfer_v2<InDataType,
                                             InDataType,
                                             decltype(in_grid_1d_desc),
                                             decltype(thread_buffer_desc_m),
                                             Sequence<InVectorSize>, // SliceLengths
                                             Sequence<0>,            // DimAccessOrder
                                             0,                      // SrcVectorDim
                                             InVectorSize,           // ScalarPerVector
                                             1,                      // SrcScalarStrideInVector
                                             false>{in_grid_1d_desc, thread_global_offset};

        auto indices_global_load =
            ThreadwiseTensorSliceTransfer_v2<IndexDataType,
                                             IndexDataType,
                                             decltype(in_grid_1d_desc),
                                             decltype(thread_buffer_desc_m),
                                             Sequence<InVectorSize>, // SliceLengths
                                             Sequence<0>,            // DimAccessOrder
                                             0,                      // SrcVectorDim
                                             InVectorSize,           // ScalarPerVector
                                             1,                      // SrcScalarStrideInVector
                                             false>{in_grid_1d_desc, thread_global_offset};

        index_t num_iter = M / loop_step;
        do
        {
            in_global_load.Run(in_grid_1d_desc,
                               in_global_buf,
                               thread_buffer_desc_m,
                               make_tuple(I0),
                               in_thread_buf);

            in_global_load.MoveSrcSliceWindow(in_grid_1d_desc, loop_step_index);

            static_for<0, InVectorSize, 1>{}(
                [&](auto iM) { elementwise_op(in_thread_buf(iM), in_thread_buf[iM]); });

            indices_global_load.Run(in_grid_1d_desc,
                                    indices_global_buf,
                                    thread_buffer_desc_m,
                                    make_tuple(I0),
                                    indices_thread_buf);

            indices_global_load.MoveSrcSliceWindow(in_grid_1d_desc, loop_step_index);

            static_for<0, InVectorSize, 1>{}([&](auto iM) {
                if(indices_thread_buf[iM] >= 0)
                {
                    if constexpr(MemOp == InMemoryDataOperationEnum::Set)
                    {
                        // User should guarantee each index in p_indices_global is different
                        *(p_out_global + indices_thread_buf[iM]) =
                            ck::type_convert<OutDataType>(in_thread_buf[iM]);
                    }
                    else if constexpr(MemOp == InMemoryDataOperationEnum::AtomicAdd)
                    {
                        atomic_add<OutDataType>(p_out_global + indices_thread_buf[iM],
                                                ck::type_convert<OutDataType>(in_thread_buf[iM]));
                    }
                    else if constexpr(MemOp == InMemoryDataOperationEnum::AtomicMax)
                    {
                        atomic_max<OutDataType>(p_out_global + indices_thread_buf[iM],
                                                ck::type_convert<OutDataType>(in_thread_buf[iM]));
                    }
                    else if constexpr(MemOp == InMemoryDataOperationEnum::Add)
                    {
                        // User should guarantee each index in p_indices_global is different
                        *(p_out_global + indices_thread_buf[iM]) +=
                            ck::type_convert<OutDataType>(in_thread_buf[iM]);
                    }
                    else
                    {
                        static_assert(MemOp == InMemoryDataOperationEnum::Set ||
                                      MemOp == InMemoryDataOperationEnum::AtomicAdd ||
                                      MemOp == InMemoryDataOperationEnum::AtomicMax ||
                                      MemOp == InMemoryDataOperationEnum::Add);
                    }
                }
            });

        } while(--num_iter);
    }

template <index_t BlockSize, typename DataType, typename Grid1dBufferDescType>
__global__ void kernel_buffer_set_value(const Grid1dBufferDescType grid_1d_buffer_desc,
                                        DataType* const __restrict__ p_global,
                                        DataType value)

{

    using PassThroughOp = tensor_operation::element_wise::PassThrough;

    constexpr auto I0 = Number<0>{};

    const index_t thread_local_id = get_thread_local_1d_id();
    const index_t block_global_id = get_block_1d_id();

    const index_t thread_global_id = block_global_id * BlockSize + thread_local_id;

    StaticBuffer<AddressSpaceEnum::Vgpr, DataType, 1, true> value_buf;

    value_buf(I0) = value;

    constexpr auto val_buff_desc = make_naive_tensor_descriptor_packed(make_tuple(Number<1>{}));

    auto global_buf = make_dynamic_buffer<AddressSpaceEnum::Global>(
        p_global, grid_1d_buffer_desc.GetElementSpaceSize());

    if(thread_global_id < grid_1d_buffer_desc.GetElementSize())
    {
        auto threadwise_store = ThreadwiseTensorSliceTransfer_v1r3<DataType,
                                                                   DataType,
                                                                   decltype(val_buff_desc),
                                                                   Grid1dBufferDescType,
                                                                   PassThroughOp,
                                                                   Sequence<1>,
                                                                   Sequence<0>,
                                                                   0,
                                                                   1,
                                                                   InMemoryDataOperationEnum::Set,
                                                                   1,
                                                                   true>(
            grid_1d_buffer_desc, make_multi_index(thread_global_id), PassThroughOp{});

        threadwise_store.Run(
            val_buff_desc, make_tuple(I0), value_buf, grid_1d_buffer_desc, global_buf);
    }
}

template <typename Grid1dBufferDescTuple,
          index_t NumBuffer,
          index_t BlockSize,
          typename DataTypePointerTuple,
          typename DataTypeTuple>
__global__ void
kernel_multiple_buffer_set_value(const Grid1dBufferDescTuple grid_1d_buffer_desc_tuple,
                                 DataTypePointerTuple p_global_tuple,
                                 DataTypeTuple value_tuple)

{
    static_assert(NumBuffer == DataTypePointerTuple::Size() && NumBuffer == DataTypeTuple::Size(),
                  "The tuple size should be same as NumBuffer!");

    static_for<0, NumBuffer, 1>{}([&](auto iB) {
        using DataTypePointer     = remove_cvref_t<decltype(DataTypePointerTuple{}[iB])>;
        using DataTypeFromPointer = remove_pointer_t<DataTypePointer>;
        using DataType            = remove_cvref_t<decltype(DataTypeTuple{}[iB])>;

        static_assert(is_same<DataType, DataTypeFromPointer>::value,
                      "Types in tuples does not match!");
    });

    constexpr auto I0 = Number<0>{};

    const index_t thread_global_id = get_thread_global_1d_id();

    auto value_buf_tuple = generate_tuple(
        [&](auto iB) {
            using DataType = remove_cvref_t<decltype(DataTypeTuple{}[iB])>;

            return StaticBuffer<AddressSpaceEnum::Vgpr, DataType, 1, true>{};
        },
        Number<NumBuffer>{});

    static_for<0, NumBuffer, 1>{}([&](auto iB) {
        static_for<0, 1, 1>{}([&](auto J) { value_buf_tuple(iB)(J) = value_tuple[iB]; });
    });

    auto global_buf_tuple = generate_tuple(
        [&](auto iB) {
            return make_dynamic_buffer<AddressSpaceEnum::Global>(
                p_global_tuple(iB), grid_1d_buffer_desc_tuple[iB].GetElementSpaceSize());
        },
        Number<NumBuffer>{});

    constexpr auto val_buff_desc = make_naive_tensor_descriptor_packed(make_tuple(Number<1>{}));

    static_for<0, NumBuffer, 1>{}([&](auto iB) {
        using DataType      = remove_cvref_t<decltype(DataTypeTuple{}[iB])>;
        using PassThroughOp = tensor_operation::element_wise::PassThrough;

        auto threadwise_store =
            ThreadwiseTensorSliceTransfer_v1r3<DataType,
                                               DataType,
                                               decltype(val_buff_desc),
                                               decltype(Grid1dBufferDescTuple{}[iB]),
                                               PassThroughOp,
                                               Sequence<1>,
                                               Sequence<0>,
                                               0,
                                               1,
                                               InMemoryDataOperationEnum::Set,
                                               1,
                                               true>(
                grid_1d_buffer_desc_tuple[iB], make_multi_index(thread_global_id), PassThroughOp{});

        threadwise_store.Run(val_buff_desc,
                             make_tuple(I0),
                             value_buf_tuple(iB),
                             grid_1d_buffer_desc_tuple[iB],
                             global_buf_tuple(iB));
    });
}

