    if(p_completed == nullptr)
    {
        return;
    }

    uint64_t& i = *p_completed;
    i           = 0;

    if(p_test == nullptr)
    {
        return;
    }

    ck::float32_t float32_in(1.0f);
    ck::float32_t float32_out{};

    auto bf6x32_vec = bf6_convert_rne(float32_in);
