template <typename DataType,
          typename GemmTraits,
          ck::index_t scalar_per_vector,
          typename BlockShape,
          typename ThreadLayout>
__global__ void __CK_WRAPPER_LAUNCH_BOUNDS__ DeviceGemm(const void* p_a,
                                                        const void* p_b,
                                                        void* p_c,
                                                        const ck::index_t M,
                                                        const ck::index_t N,
                                                        const ck::index_t K,
                                                        const BlockShape tile_shape,
                                                        const ThreadLayout thread_layout)
{
    constexpr auto MPerBlock = ck::wrapper::size<0>(tile_shape);
    constexpr auto NPerBlock = ck::wrapper::size<1>(tile_shape);
    constexpr auto KPerBlock = ck::wrapper::size<2>(tile_shape);

    // Specify layouts for global memory.
    const auto a_global_layout =
        ck::wrapper::make_layout(ck::make_tuple(M, K), ck::make_tuple(K, 1));
    const auto b_global_layout =
        ck::wrapper::make_layout(ck::make_tuple(N, K), ck::make_tuple(K, 1));
    const auto c_global_layout =
        ck::wrapper::make_layout(ck::make_tuple(M, N), ck::make_tuple(N, 1));
    // Specify layouts for tiles.
    constexpr auto a_tile_layout = ck::wrapper::make_layout(
        ck::make_tuple(MPerBlock, KPerBlock), ck::make_tuple(KPerBlock, ck::Number<1>{}));
    constexpr auto b_tile_layout = ck::wrapper::make_layout(
        ck::make_tuple(NPerBlock, KPerBlock), ck::make_tuple(KPerBlock, ck::Number<1>{}));
    constexpr auto c_tile_layout = ck::wrapper::make_layout(
        ck::make_tuple(MPerBlock, NPerBlock), ck::make_tuple(NPerBlock, ck::Number<1>{}));
    // Apply padding for global memory.
    auto a_global_layout_padded = ck::wrapper::pad(a_global_layout, shape(a_tile_layout));
    auto b_global_layout_padded = ck::wrapper::pad(b_global_layout, shape(b_tile_layout));
    auto c_global_layout_padded = ck::wrapper::pad(c_global_layout, shape(c_tile_layout));
    // Make tensors for global memory.
    auto a_global_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Global>(
        static_cast<const DataType*>(p_a), a_global_layout_padded);
    auto b_global_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Global>(
        static_cast<const DataType*>(p_b), b_global_layout_padded);
    auto c_global_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Global>(
        static_cast<DataType*>(p_c), c_global_layout_padded);
    // Allocate lds memory.
    __shared__ DataType lds_a[ck::wrapper::size(a_tile_layout)];
    __shared__ DataType lds_b[ck::wrapper::size(b_tile_layout)];
    // Make tensors for lds memory.
    auto a_lds_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Lds>(
        static_cast<DataType*>(lds_a), a_tile_layout);
    auto b_lds_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Lds>(
        static_cast<DataType*>(lds_b), b_tile_layout);
    // Specify block index as tuple.
    const auto block_idxs = ck::make_tuple(static_cast<ck::index_t>(blockIdx.x),
                                           static_cast<ck::index_t>(blockIdx.y),
                                           ck::wrapper::slice());
    // Specify access parameters for copy.
    using DimAccessOrder             = ck::Tuple<ck::Number<0>, ck::Number<1>>;
    constexpr ck::index_t vector_dim = 1;
    // Create tile and partition for C. Use specific function for blockwise_gemm to assign the
    // appropriate partitions.
    auto c_global_local_tile = ck::wrapper::make_local_tile(
        c_global_tensor,
        tile_shape,
        block_idxs,
        make_tuple(ck::Number<1>{}, ck::Number<1>{}, ck::wrapper::slice(KPerBlock)));
    auto c_global_local_partition =
        ck::wrapper::make_blockwise_gemm_xdl_c_local_partition<DataType,
                                                               decltype(a_tile_layout),
                                                               decltype(b_tile_layout),
                                                               ck::wrapper::size(thread_layout),
                                                               GemmTraits>(c_global_local_tile);
    // Create C vgpr to accumulate results.
    auto c_vgpr_reg = ck::wrapper::make_blockwise_gemm_xdl_c_vgpr<DataType,
                                                                  decltype(a_tile_layout),
                                                                  decltype(b_tile_layout),
                                                                  ck::wrapper::size(thread_layout),
                                                                  GemmTraits>();
    // Clear C vgpr.
    ck::wrapper::clear(c_vgpr_reg);

    // Iterate over K with KPerBlock step.
    const ck::index_t num_loop = ck::math::integer_divide_ceil(K, KPerBlock);
    ck::index_t i              = 0;
    do
    {
        // Get KPerBlock slice.
        const auto k_slice           = ck::wrapper::slice(i * KPerBlock, (i + 1) * KPerBlock);
        auto a_global_tensor_k_slice = a_global_tensor(ck::wrapper::slice(), k_slice);
        auto b_global_tensor_k_slice = b_global_tensor(ck::wrapper::slice(), k_slice);
        // Create local tiles for A and B.
        auto a_global_local_tile = ck::wrapper::make_local_tile(
            a_global_tensor_k_slice,
            tile_shape,
            block_idxs,
            make_tuple(ck::Number<1>{}, ck::wrapper::slice(N), ck::Number<1>{}));
        auto b_global_local_tile = ck::wrapper::make_local_tile(
            b_global_tensor_k_slice,
            tile_shape,
            block_idxs,
            make_tuple(ck::wrapper::slice(M), ck::Number<1>{}, ck::Number<1>{}));
        // Copy from global to lds.
        ck::wrapper::blockwise_copy<DimAccessOrder, vector_dim, scalar_per_vector>(
            a_global_local_tile, a_lds_tensor, thread_layout);
        ck::wrapper::blockwise_copy<DimAccessOrder, vector_dim, scalar_per_vector>(
            b_global_local_tile, b_lds_tensor, thread_layout);
        // Synchronize lds.
        ck::block_sync_lds();
        // Execute blockwise gemm.
        ck::wrapper::blockwise_gemm_xdl<DataType, ck::wrapper::size(thread_layout), GemmTraits>(
            a_lds_tensor, b_lds_tensor, c_vgpr_reg);

        ++i;
    } while(i < num_loop);
    // Copy vgpr results to C global memory.
    ck::wrapper::copy(c_vgpr_reg, c_global_local_partition);
}

template <typename InputTensor, typename OutputTensor, typename BlockShape, typename ThreadLayout>
__global__ void __CK_WRAPPER_LAUNCH_BOUNDS__
DeviceImageToColumnPad0(InputTensor input_tensor,
                        OutputTensor output_tensor,
                        const BlockShape tile_shape,
                        const ThreadLayout thread_layout)
{
    // grid layout (dim1, dim0)
    const auto block_idxs =
        ck::make_tuple(static_cast<ck::index_t>(blockIdx.y), static_cast<ck::index_t>(blockIdx.x));

    // Get local tiles for global memory
    auto input_local_tile  = ck::wrapper::make_local_tile(input_tensor, tile_shape, block_idxs);
    auto output_local_tile = ck::wrapper::make_local_tile(output_tensor, tile_shape, block_idxs);

    // Get partition per thread
    const auto input_local_partition =
        ck::wrapper::make_local_partition(input_local_tile, thread_layout, threadIdx.x);
    auto output_local_partition =
        ck::wrapper::make_local_partition(output_local_tile, thread_layout, threadIdx.x);

    // Perform copy
    using DimAccessOrder                    = ck::Tuple<ck::Number<0>, ck::Number<1>>;
    constexpr ck::index_t vector_dim        = 1;
    constexpr ck::index_t scalar_per_vector = 4;
    ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(input_local_partition,
                                                                     output_local_partition);
}

template <bool DoPad, typename Layout, typename PaddingDims>
__device__ auto ApplyPadding(const Layout& layout, const PaddingDims& padding_dims)
{
    if constexpr(DoPad)
    {
        return ck::wrapper::pad(layout, padding_dims);
    }
    else
    {
        return layout;
    }
}

template <typename DataType,
          typename GemmTraits,
          ck::index_t scalar_per_vector,
          typename BlockShape,
          typename ThreadLayout,
          bool DoPadding>
__global__ void __CK_WRAPPER_LAUNCH_BOUNDS__ DeviceGemm(const void* p_a,
                                                        const void* p_b,
                                                        void* p_c,
                                                        const ck::index_t M,
                                                        const ck::index_t N,
                                                        const ck::index_t K,
                                                        const BlockShape tile_shape,
                                                        const ThreadLayout thread_layout)
{
    constexpr auto MPerBlock  = ck::wrapper::size<0>(tile_shape);
    constexpr auto NPerBlock  = ck::wrapper::size<1>(tile_shape);
    constexpr auto KPerBlock  = ck::wrapper::size<2>(tile_shape);
    constexpr auto K1         = GemmTraits::K1;
    constexpr auto K0PerBlock = KPerBlock / K1;
    const auto K0             = ck::math::integer_divide_ceil(K, K1);

    const auto tile_shape_k0_m_n_k1 = ck::make_tuple(K0PerBlock, MPerBlock, NPerBlock, K1);
    // Create layouts for global memory
    const auto a_global_layout =
        ck::wrapper::make_layout(ck::make_tuple(M, K), ck::make_tuple(K, 1));
    const auto b_global_layout =
        ck::wrapper::make_layout(ck::make_tuple(N, K), ck::make_tuple(K, 1));
    const auto c_global_layout =
        ck::wrapper::make_layout(ck::make_tuple(M, N), ck::make_tuple(N, 1));
    // Apply padding
    auto a_padded_global_layout =
        ApplyPadding<DoPadding>(a_global_layout, ck::make_tuple(MPerBlock, KPerBlock));
    auto b_padded_global_layout =
        ApplyPadding<DoPadding>(b_global_layout, ck::make_tuple(NPerBlock, KPerBlock));
    auto c_padded_global_layout =
        ApplyPadding<DoPadding>(c_global_layout, ck::make_tuple(MPerBlock, NPerBlock));
    // Reshape from M,K to K0,M,K1
    const auto reshaped_dims_idxs =
        ck::make_tuple(ck::Number<1>{}, ck::make_tuple(ck::Number<0>{}, ck::Number<2>{}));
    auto a_padded_unmerged_global_layout =
        ck::wrapper::unmerge<1>(a_padded_global_layout, ck::make_tuple(K0, K1), reshaped_dims_idxs);
    auto b_padded_unmerged_global_layout =
        ck::wrapper::unmerge<1>(b_padded_global_layout, ck::make_tuple(K0, K1), reshaped_dims_idxs);
    // Create tensors for global memory
    auto a_global_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Global>(
        static_cast<const DataType*>(p_a), a_padded_unmerged_global_layout);
    auto b_global_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Global>(
        static_cast<const DataType*>(p_b), b_padded_unmerged_global_layout);
    auto c_global_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Global>(
        static_cast<DataType*>(p_c), c_padded_global_layout);
    // Create layouts and tensors for lds memory.
    constexpr auto a_tile_layout = ck::wrapper::make_layout(
        ck::make_tuple(K0PerBlock, MPerBlock, K1),
        ck::make_tuple((MPerBlock + ck::Number<1>{}) * K1, K1, ck::Number<1>{}));
    constexpr auto b_tile_layout = ck::wrapper::make_layout(
        ck::make_tuple(K0PerBlock, NPerBlock, K1),
        ck::make_tuple((NPerBlock + ck::Number<1>{}) * K1, K1, ck::Number<1>{}));

    __shared__ DataType lds_a[ck::wrapper::size(a_tile_layout) + K0PerBlock];
    __shared__ DataType lds_b[ck::wrapper::size(b_tile_layout) + K0PerBlock];

    auto a_lds_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Lds>(
        static_cast<DataType*>(lds_a), a_tile_layout);
    auto b_lds_tensor = ck::wrapper::make_tensor<ck::wrapper::MemoryTypeEnum::Lds>(
        static_cast<DataType*>(lds_b), b_tile_layout);

    const auto block_idxs            = ck::make_tuple(ck::wrapper::slice(),
                                           static_cast<ck::index_t>(blockIdx.x),
                                           static_cast<ck::index_t>(blockIdx.y),
                                           ck::wrapper::slice());
    using DimAccessOrder             = ck::Tuple<ck::Number<1>, ck::Number<0>, ck::Number<2>>;
    constexpr ck::index_t vector_dim = 2;

    // Create tile and partition for C global memory. Use specific gemm
    // functions to get appropriate layouts.
    auto c_global_local_tile =
        ck::wrapper::make_local_tile(c_global_tensor,
                                     tile_shape_k0_m_n_k1,
                                     block_idxs,
                                     make_tuple(ck::wrapper::slice(K0PerBlock),
                                                ck::Number<1>{},
                                                ck::Number<1>{},
                                                ck::wrapper::slice(K1)));
    auto c_global_local_partition =
        ck::wrapper::make_blockwise_gemm_xdl_c_local_partition<DataType,
                                                               decltype(a_tile_layout),
                                                               decltype(b_tile_layout),
                                                               ck::wrapper::size(thread_layout),
                                                               GemmTraits>(c_global_local_tile);
    // Define and clear c vgpr register
    auto c_vgpr_reg = ck::wrapper::make_blockwise_gemm_xdl_c_vgpr<DataType,
                                                                  decltype(a_tile_layout),
                                                                  decltype(b_tile_layout),
                                                                  ck::wrapper::size(thread_layout),
                                                                  GemmTraits>();
    ck::wrapper::clear(c_vgpr_reg);
    // Local partitions for lds memory
    auto a_lds_tensor_local_partition =
        ck::wrapper::make_local_partition(a_lds_tensor, thread_layout, threadIdx.x);
    auto b_lds_tensor_local_partition =
        ck::wrapper::make_local_partition(b_lds_tensor, thread_layout, threadIdx.x);
    // Lamda to slice tensor, then create local tile and partition
    auto make_global_partition = [&](auto tensor, auto projection, ck::index_t i) {
        const auto k_slice =
            ck::make_tuple(ck::wrapper::slice(i * K0PerBlock, (i + 1) * K0PerBlock),
                           ck::wrapper::slice(),
                           ck::wrapper::slice());
        auto local_tile = ck::wrapper::make_local_tile(
            tensor(k_slice), tile_shape_k0_m_n_k1, block_idxs, projection);
        return ck::wrapper::make_local_partition(local_tile, thread_layout, threadIdx.x);
    };

    auto a_global_local_partition = make_global_partition(
        a_global_tensor,
        make_tuple(ck::Number<1>{}, ck::Number<1>{}, ck::wrapper::slice(N), ck::Number<1>{}),
        0);
    auto b_global_local_partition = make_global_partition(
        b_global_tensor,
        make_tuple(ck::Number<1>{}, ck::wrapper::slice(M), ck::Number<1>{}, ck::Number<1>{}),
        0);

    // (row-major vgpr layout)
    auto a_vgpr_tensor =
        ck::wrapper::make_register_tensor<ck::wrapper::MemoryTypeEnum::Vgpr, DataType>(
            ck::wrapper::make_layout(
                shape(a_global_local_partition),
                ck::make_tuple(ck::wrapper::size<1>(a_global_local_partition) *
                                   ck::wrapper::size<2>(a_global_local_partition),
                               ck::wrapper::size<2>(a_global_local_partition),
                               ck::Number<1>{})));
    auto b_vgpr_tensor =
        ck::wrapper::make_register_tensor<ck::wrapper::MemoryTypeEnum::Vgpr, DataType>(
            ck::wrapper::make_layout(
                shape(b_global_local_partition),
                ck::make_tuple(ck::wrapper::size<1>(a_global_local_partition) *
                                   ck::wrapper::size<2>(a_global_local_partition),
                               ck::wrapper::size<2>(a_global_local_partition),
                               ck::Number<1>{})));
    // Copy first values to lds
    ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(a_global_local_partition,
                                                                     a_vgpr_tensor);
    ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(b_global_local_partition,
                                                                     b_vgpr_tensor);
    ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(a_vgpr_tensor,
                                                                     a_lds_tensor_local_partition);
    ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(b_vgpr_tensor,
                                                                     b_lds_tensor_local_partition);
    // Pipeline loop
    const ck::index_t num_loop =
        __builtin_amdgcn_readfirstlane(ck::math::integer_divide_ceil(K, KPerBlock));
    // Skip if only tile should be processed
    if(num_loop > 1)
    {
        ck::index_t i = 0;
        do
        {
            auto a_global_local_partition_i = make_global_partition(
                a_global_tensor,
                make_tuple(
                    ck::Number<1>{}, ck::Number<1>{}, ck::wrapper::slice(N), ck::Number<1>{}),
                i + 1);
            auto b_global_local_partition_i = make_global_partition(
                b_global_tensor,
                make_tuple(
                    ck::Number<1>{}, ck::wrapper::slice(M), ck::Number<1>{}, ck::Number<1>{}),
                i + 1);
            // Copy data to A vgpr.
            ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(
                a_global_local_partition_i, a_vgpr_tensor);
            // Synchronize.
            ck::block_sync_lds();
            // Copy data to B vgpr.
            ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(
                b_global_local_partition_i, b_vgpr_tensor);
            // Perform gemm.
            ck::wrapper::blockwise_gemm_xdl<DataType, ck::wrapper::size(thread_layout), GemmTraits>(
                a_lds_tensor, b_lds_tensor, c_vgpr_reg);
            // Synchronize
            ck::block_sync_lds();
            // Copy data to A and B lds tiles.
            ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(
                a_vgpr_tensor, a_lds_tensor_local_partition);
            ck::wrapper::copy<DimAccessOrder, vector_dim, scalar_per_vector>(
                b_vgpr_tensor, b_lds_tensor_local_partition);

            ++i;
        } while(i < (num_loop - 1));
    }
    // Handle tail.
    ck::block_sync_lds();
    ck::wrapper::blockwise_gemm_xdl<DataType, ck::wrapper::size(thread_layout), GemmTraits>(
        a_lds_tensor, b_lds_tensor, c_vgpr_reg);
    // Store data from C vgpr to C global memory.
    ck::wrapper::copy(c_vgpr_reg, c_global_local_partition);
}

template <typename T>
__device__ __host__ inline auto fetch_asum(T A)
{
    return A < 0 ? -A : A;
}

__device__ void operator()(rocblas_int tx, T* x) const
    {
        // Reduce the lower half with the upper half
        if(tx < k)
            REDUCE{}(x[tx], x[tx + k]);
        __syncthreads();

        // Recurse down with k / 2
        rocblas_reduction_s<k / 2, REDUCE, T>{}(tx, x);
    }

__device__ void rocblas_reduction(rocblas_int tx, T* x)
{
    static_assert(NB > 1 && !(NB & (NB - 1)), "NB must be a power of 2");
    __syncthreads();
    rocblas_reduction_s<NB / 2, REDUCE, T>{}(tx, x);
}

__device__ void operator()(T& __restrict__ a, const T& __restrict__ b) const
    {
        a += b;
    }

__device__ void rocblas_sum_reduce(rocblas_int tx, T* x)
{
    rocblas_reduction<NB, rocblas_reduce_sum>(tx, x);
}

__device__ T&& operator()(T&& x)
    {
        return std::forward<T>(x); // Perfect identity, preserving valueness
    }

__device__ void
    rocblas_dot_save_sum(V sum, size_t batch, V* __restrict__ workspace, T* __restrict__ out)
{
    if(threadIdx.x == 0)
    {
        if(ONE_BLOCK || gridDim.x == 1) // small N avoid second kernel
            out[batch] = T(sum);
        else
            workspace[blockIdx.x + batch * gridDim.x] = sum;
    }
}

__device__ constexpr auto operator()() const
    {
        rocblas_index_value_t<T> x;
        x.index = 0;
        return x;
    }

__device__ rocblas_index_value_t<To>
                                        operator()(Ti x, rocblas_int index) const
    {
        return {index, fetch_asum(x)};
    }

__device__ void
        operator()(rocblas_index_value_t<To>& __restrict__ x,
                   const rocblas_index_value_t<To>& __restrict__ y) const
    {
        // If y.index == 0 then y.value is invalid and should not be compared
        if(y.index != 0)
        {
            if(x.index == 0 || y.value > x.value)
                x = y; // if larger or smaller, update max/min and index
            else if(y.index < x.index && x.value == y.value)
                x.index = y.index; // if equal, choose smaller index
        }
    }

__device__ void
        operator()(rocblas_index_value_t<To>& __restrict__ x,
                   const rocblas_index_value_t<To>& __restrict__ y) const
    {
        // If y.index == 0 then y.value is invalid and should not be compared
        if(y.index != 0)
        {
            if(x.index == 0 || y.value < x.value)
                x = y; // if larger or smaller, update max/min and index
            else if(y.index < x.index && x.value == y.value)
                x.index = y.index; // if equal, choose smaller index
        }
    }

__device__ rocblas_index_value_t<T>
                      rocblas_wavefront_reduce_method(rocblas_index_value_t<T> x)
{
    constexpr int WFBITS = rocblas_log2ui(WARP);
    int           offset = 1 << (WFBITS - 1);
    for(int i = 0; i < WFBITS; i++)
    {
        rocblas_index_value_t<T> y{};
        y.index = __shfl_down(x.index, offset);
        y.value = __shfl_down(x.value, offset);
        REDUCE{}(x, y);
        offset >>= 1;
    }
    return x;
}

__device__ T rocblas_shuffle_block_reduce_method(T val)
{
    __shared__ T psums[WARP];

    rocblas_int wavefront = threadIdx.x / WARP;
    rocblas_int wavelet   = threadIdx.x % WARP;

    if(wavefront == 0)
        psums[wavelet] = T{};
    __syncthreads();

    val = rocblas_wavefront_reduce_method<WARP, REDUCE>(val); // sum over wavefront
    if(wavelet == 0)
        psums[wavefront] = val; // store sum for wavefront

    __syncthreads(); // Wait for all wavefront reductions

    // ensure wavefront was run
    static constexpr rocblas_int NUM_WARPS = NB / WARP;
    val                                    = (threadIdx.x < NUM_WARPS) ? psums[wavelet] : T{};
    if(wavefront == 0)
        val = rocblas_wavefront_reduce_method<NUM_WARPS, REDUCE>(val); // sum wavefront sums

    return val;
}

__device__ T rocblas_wavefront_reduce(T val)
{
    constexpr int WFBITS = rocblas_log2ui(N);
    int           offset = 1 << (WFBITS - 1);
#pragma unroll
    for(int i = 0; i < WFBITS; i++)
    {
        val += __shfl_down(val, offset);
        offset >>= 1;
    }
    return val;
}

__device__ rocblas_float_complex rocblas_wavefront_reduce(rocblas_float_complex val)
{
    constexpr int WFBITS = rocblas_log2ui(N);
    int           offset = 1 << (WFBITS - 1);
#pragma unroll
    for(int i = 0; i < WFBITS; i++)
    {
        val.real(val.real() + __shfl_down(val.real(), offset));
        val.imag(val.imag() + __shfl_down(val.imag(), offset));
        offset >>= 1;
    }
    return val;
}

__device__ rocblas_double_complex rocblas_wavefront_reduce(rocblas_double_complex val)
{
    constexpr int WFBITS = rocblas_log2ui(N);
    int           offset = 1 << (WFBITS - 1);
#pragma unroll
    for(int i = 0; i < WFBITS; i++)
    {
        val.real(val.real() + __shfl_down(val.real(), offset));
        val.imag(val.imag() + __shfl_down(val.imag(), offset));
        offset >>= 1;
    }
    return val;
}

__device__ rocblas_bfloat16 rocblas_wavefront_reduce(rocblas_bfloat16 val)
{
    union
    {
        int              i;
        rocblas_bfloat16 h;
    } tmp;
    constexpr int WFBITS = rocblas_log2ui(N);
    int           offset = 1 << (WFBITS - 1);
#pragma unroll
    for(int i = 0; i < WFBITS; i++)
    {
        tmp.h = val;
        tmp.i = __shfl_down(tmp.i, offset);
        val += tmp.h;
        offset >>= 1;
    }
    return val;
}

__device__ rocblas_half rocblas_wavefront_reduce(rocblas_half val)
{
    union
    {
        int          i;
        rocblas_half h;
    } tmp;
    constexpr int WFBITS = rocblas_log2ui(N);
    int           offset = 1 << (WFBITS - 1);
#pragma unroll
    for(int i = 0; i < WFBITS; i++)
    {
        tmp.h = val;
        tmp.i = __shfl_down(tmp.i, offset);
        val += tmp.h;
        offset >>= 1;
    }
    return val;
}

__device__ T rocblas_dot_block_reduce(T val)
{
    __shared__ T psums[WARP];

    rocblas_int wavefront = threadIdx.x / WARP;
    rocblas_int wavelet   = threadIdx.x % WARP;

    if(wavefront == 0)
        psums[wavelet] = T(0);
    __syncthreads();

    val = rocblas_wavefront_reduce<WARP>(val); // sum over wavefront
    if(wavelet == 0)
        psums[wavefront] = val; // store sum for wavefront

    __syncthreads(); // Wait for all wavefront reductions

    // ensure wavefront was run
    static constexpr rocblas_int num_wavefronts = NB / WARP;

    // single warp of either size will doing final sum so test with smaller constraint
    static_assert(num_wavefronts <= WARP_32);

    val = (threadIdx.x < num_wavefronts) ? psums[wavelet] : T(0);
    if(wavefront == 0)
        val = rocblas_wavefront_reduce<num_wavefronts>(val); // sum wavefront sums

    return val;
}

__device__ void rocblas_rotm_kernel_calc(rocblas_int    n,
                                                         T              x_in,
                                                         rocblas_stride offset_x,
                                                         int64_t        incx,
                                                         rocblas_stride stride_x,
                                                         T              y_in,
                                                         rocblas_stride offset_y,
                                                         int64_t        incy,
                                                         rocblas_stride stride_y,
                                                         U              flag,
                                                         U              h11,
                                                         U              h21,
                                                         U              h12,
                                                         U              h22,
                                                         rocblas_int    batch)
{
    auto    x   = load_ptr_batch(x_in, batch, offset_x, stride_x);
    auto    y   = load_ptr_batch(y_in, batch, offset_y, stride_y);
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;

    if(tid < n && flag != -2)
    {
        int64_t ix = tid * incx;
        int64_t iy = tid * incy;
        auto    w  = x[ix];
        auto    z  = y[iy];
        if(flag < 0)
        {
            //cppcheck-suppress unreadVariable # The variables 'x' and 'y' will be copied back to host(CPU)
            x[ix] = w * h11 + z * h12;
            //cppcheck-suppress unreadVariable # The variables 'x' and 'y' will be copied back to host(CPU)
            y[iy] = w * h21 + z * h22;
        }
        else if(flag == 0)
        {
            //cppcheck-suppress unreadVariable # The variables 'x' and 'y' will be copied back to host(CPU)
            x[ix] = w + z * h12;
            //cppcheck-suppress unreadVariable # The variables 'x' and 'y' will be copied back to host(CPU)
            y[iy] = w * h21 + z;
        }
        else
        {
            //cppcheck-suppress unreadVariable # The variables 'x' and 'y' will be copied back to host(CPU)
            x[ix] = w * h11 + z;
            //cppcheck-suppress unreadVariable # The variables 'x' and 'y' will be copied back to host(CPU)
            y[iy] = -w + z * h22;
        }
    }
}

__device__ void
    rocblas_rot_kernel_calc(rocblas_int n, Tx* x, int64_t incx, Ty* y, int64_t incy, Tc c, Ts s)
{
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;

    if(tid < n)
    {
        int64_t ix    = tid * incx;
        int64_t iy    = tid * incy;
        Tex     tempx = Tex(c * x[ix]) + Tex(s * y[iy]);
        Tex     tempy = Tex(c * y[iy]) - Tex((s)*x[ix]);
        y[iy]         = Ty(tempy);
        x[ix]         = Tx(tempx);
    }
}

__device__ void
    rocblas_rot_kernel_calc(rocblas_int n, Tx* x, int64_t incx, Ty* y, int64_t incy, Tc c, Ts s)
{
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;

    if(tid < n)
    {
        int64_t ix    = tid * incx;
        int64_t iy    = tid * incy;
        Tex     tempx = Tex(c * x[ix]) + Tex(s * y[iy]);
        Tex     tempy = Tex(c * y[iy]) - Tex(conj(s) * x[ix]);
        y[iy]         = Ty(tempy);
        x[ix]         = Tx(tempx);
    }
}

__device__ __host__ void rocblas_swap_vals(T* __restrict__ x, T* __restrict__ y)
{
    T tmp = *y;
    *y    = *x;
    *x    = tmp;
}

__device__ __host__ void rocblas_rotg_calc(T& a, T& b, U& c, T& s)
{
    T scale = rocblas_abs(a) + rocblas_abs(b);
    if(scale == 0.0)
    {
        c = 1.0;
        s = 0.0;
        a = 0.0;
        b = 0.0;
    }
    else
    {
        T sa  = a / scale;
        T sb  = b / scale;
        T r   = scale * sqrt(sa * sa + sb * sb);
        T roe = rocblas_abs(a) > rocblas_abs(b) ? a : b;
        r     = copysign(r, roe);
        c     = a / r;
        s     = b / r;
        T z   = 1.0;
        if(rocblas_abs(a) > rocblas_abs(b))
            z = s;
        if(rocblas_abs(b) >= rocblas_abs(a) && c != 0.0)
            z = 1.0 / c;
        a = r;
        b = z;
    }
}

__device__ __host__ void rocblas_rotg_calc(T& a, T& b, U& c, T& s)
{
    if(rocblas_abs(a) != 0.)
    {
        auto scale = rocblas_abs(a) + rocblas_abs(b);
        auto sa    = rocblas_abs(a / scale);
        auto sb    = rocblas_abs(b / scale);
        auto norm  = scale * sqrt(sa * sa + sb * sb);
        auto alpha = a / rocblas_abs(a);
        c          = rocblas_abs(a) / norm;
        s          = alpha * conj(b) / norm;
        a          = alpha * norm;
    }
    else
    {
        c = 0;
        s = {1, 0};
        a = b;
    }
}

__device__ __host__ void
    rocblas_rotmg_calc(T& d1, T& d2, T& x1, const T& y1, T* param)
{
    constexpr T gam    = 4096;
    constexpr T rgam   = 1 / gam;
    constexpr T gamsq  = gam * gam;
    constexpr T rgamsq = 1 / gamsq;

    T flag = -1;
    T h11 = 0, h21 = 0, h12 = 0, h22 = 0;

    if(d1 < 0)
    {
        d1 = d2 = x1 = 0;
    }
    else
    {
        T p2 = d2 * y1;
        if(p2 == 0)
        {
            flag     = -2;
            param[0] = flag;
            return;
        }
        T p1 = d1 * x1;
        T q2 = p2 * y1;
        T q1 = p1 * x1;
        if(rocblas_abs(q1) > rocblas_abs(q2))
        {
            h21 = -y1 / x1;
            h12 = p2 / p1;
            T u = 1 - h12 * h21;
            if(u > 0)
            {
                flag = 0;
                d1 /= u;
                d2 /= u;
                x1 *= u;
            }
        }
        else
        {
            if(q2 < 0)
            {
                d1 = d2 = x1 = 0;
            }
            else
            {
                flag   = 1;
                h11    = p1 / p2;
                h22    = x1 / y1;
                T u    = 1 + h11 * h22;
                T temp = d2 / u;
                d2     = d1 / u;
                d1     = temp;
                x1     = y1 * u;
            }
        }

        if(d1 != 0)
        {
            while((d1 <= rgamsq) || (d1 >= gamsq))
            {
                if(flag == 0)
                {
                    h11 = h22 = 1;
                    flag      = -1;
                }
                else
                {
                    h21  = -1;
                    h12  = 1;
                    flag = -1;
                }
                if(d1 <= rgamsq)
                {
                    d1 *= gamsq;
                    x1 *= rgam;
                    h11 *= rgam;
                    h12 *= rgam;
                }
                else
                {
                    d1 *= rgamsq;
                    x1 *= gam;
                    h11 *= gam;
                    h12 *= gam;
                }
            }
        }

        if(d2 != 0)
        {
            while((rocblas_abs(d2) <= rgamsq) || (rocblas_abs(d2) >= gamsq))
            {
                if(flag == 0)
                {
                    h11 = h22 = 1;
                    flag      = -1;
                }
                else
                {
                    h21  = -1;
                    h12  = 1;
                    flag = -1;
                }
                if(rocblas_abs(d2) <= rgamsq)
                {
                    d2 *= gamsq;
                    h21 *= rgam;
                    h22 *= rgam;
                }
                else
                {
                    d2 *= rgamsq;
                    h21 *= gam;
                    h22 *= gam;
                }
            }
        }
    }

    if(flag < 0)
    {
        param[1] = h11;
        param[2] = h21;
        param[3] = h12;
        param[4] = h22;
    }
    else if(flag == 0)
    {
        param[2] = h21;
        param[3] = h12;
    }
    else
    {
        param[1] = h11;
        param[4] = h22;
    }
    param[0] = flag;
}

__device__ void rocblas_her2_kernel_calc(bool        is_upper,
                                                         rocblas_int n,
                                                         size_t      area,
                                                         T           alpha,
                                                         const T*    x,
                                                         API_INT     incx,
                                                         const T*    y,
                                                         API_INT     incy,
                                                         T*          A,
                                                         API_INT     lda)
{
    size_t i = size_t(blockIdx.x) * blockDim.x + threadIdx.x; // linear area index
    if(i >= area)
        return;

    size_t ri = !is_upper ? area - 1 - i : i;

    // linearized triangle with diagonal to col, row
    int k  = int(sqrt(8 * ri + 1) - 1) / 2;
    int ty = k;
    int tx = ri - k * size_t(k + 1) / 2;

    if(!is_upper)
    {
        int maxIdx = n - 1;
        tx         = maxIdx - tx;
        ty         = maxIdx - ty;
    }

    if(is_upper ? tx < ty : ty < tx)
    {
        A[tx + int64_t(lda) * ty]
            += alpha * x[tx * int64_t(incx)] * conj(y[ty * int64_t(incy)])
               + conj(alpha) * y[tx * int64_t(incy)] * conj(x[ty * int64_t(incx)]);
    }
    else if(tx == ty)
    {
        A[tx + int64_t(lda) * ty]
            = std::real(A[tx + int64_t(lda) * ty])
              + alpha * x[tx * int64_t(incx)] * conj(y[ty * int64_t(incy)])
              + conj(alpha) * y[tx * int64_t(incy)] * conj(x[ty * int64_t(incx)]);
    }
}

__device__ void rocblas_gbmvn_kernel_calc(rocblas_int m,
                                                          rocblas_int n,
                                                          rocblas_int kl,
                                                          rocblas_int ku,
                                                          T           alpha,
                                                          const T*    A,
                                                          int64_t     lda,
                                                          const T*    x,
                                                          int64_t     incx,
                                                          T           beta,
                                                          T*          y,
                                                          int64_t     incy)
{
    // With the banded format, each diagonal,
    // (from bottom left to top right) is like a row in a normal
    // matrix, so the blocks are "tilted" to the right.

    // y thread specifies row to process
    rocblas_int row = blockIdx.x * DIM_Y + threadIdx.y;
    if(row >= m)
        return;

    T res_A = T(0);

    if(alpha)
    {
        int bands_minus_1 = kl + ku;

        int brow = row + ku;
        if(brow > bands_minus_1)
            brow = bands_minus_1;

        int bcol = row - kl;
        if(bcol < 0)
            bcol = 0;

        // witin warp x threads compute a row dot product so move to adjacent band (unbanded matrix next column)
        brow -= threadIdx.x;
        bcol += threadIdx.x;

        // accumulate all bands partial results
        for(; brow >= 0; brow -= WARP, bcol += WARP)
        {
            if(bcol < n)
                res_A += A[brow + bcol * lda] * x[bcol * incx];
        }
        __syncthreads();

        res_A = rocblas_wavefront_reduce<WARP>(res_A);
        res_A *= alpha;
    }

    if(threadIdx.x == 0)
    {
        if(beta != 0)
            y[row * incy] = res_A + beta * y[row * incy];
        else
            y[row * incy] = res_A;
    }
}

__device__ void rocblas_gbmvt_kernel_calc(rocblas_operation transA,
                                                          rocblas_int       m,
                                                          rocblas_int       n,
                                                          rocblas_int       kl,
                                                          rocblas_int       ku,
                                                          T                 alpha,
                                                          const T*          A,
                                                          int64_t           lda,
                                                          const T*          x,
                                                          int64_t           incx,
                                                          T                 beta,
                                                          T*                y,
                                                          int64_t           incy)
{
    rocblas_int col = blockIdx.x * DIM_Y + threadIdx.y;
    if(col >= n)
        return;

    // With the banded format each diagonal
    // (from bottom left to top right) is like a row in a normal
    // matrix, so the blocks are "tilted" to the right.

    T res_A(0);

    if(alpha)
    {
        bool is_conj = transA == rocblas_operation_conjugate_transpose;

        // We have to convert banded to unbanded

        int tx = threadIdx.x;

        int nbands = kl + ku + 1;

        A += col * lda;

        // create WARP number of partial results
        for(int row = tx; row < nbands; row += WARP)
        {
            int ku_minus_row = ku - row;

            if(col < (m + ku_minus_row))
            {
                if(row > ku || (row <= ku && col >= ku_minus_row))
                {
                    res_A += ((is_conj ? conj(A[row]) : A[row]) * x[(col - ku_minus_row) * incx]);
                }
            }
        }
        __syncthreads();

        res_A = rocblas_wavefront_reduce<WARP>(res_A);
        res_A *= alpha;
    }

    if(threadIdx.x == 0)
    {
        if(beta != 0)
            y[col * incy] = res_A + beta * y[col * incy];
        else
            y[col * incy] = res_A;
    }
}

template <rocblas_int DIM_Y, typename T>
__device__ T rocblas_hbmvn_kernel_helper(rocblas_int ty,
                                         rocblas_int ind,
                                         bool        is_upper,
                                         rocblas_int m,
                                         rocblas_int k,
                                         const T*    A,
                                         int64_t     lda,
                                         const T*    x,
                                         int64_t     incx)
{
    T           res_A = 0.0;
    rocblas_int col;

    // Since the column is consistent, we can iterate up the diagonal
    // ty defines the column of banded & regular matrix
    for(col = ty; col < m; col += DIM_Y)
    {
        // We have to convert ind to banded matrix row
        rocblas_int row = is_upper ? ind + (k - col) : ind - col;

        if(ind < m)
        {
            if((ind <= col && is_upper) || (ind >= col && !is_upper))
            {
                // in is_upper/lower triangular part
                if(row < k && row > 0)
                {
                    // not on main diagonal, simply multiply
                    res_A += (A[row + col * size_t(lda)] * x[col * incx]);
                }
                else if(row == 0)
                {
                    // cppcheck-suppress knownConditionTrueFalse
                    // If main diagonal, assume 0 imaginary part.
                    if(!is_upper || (k == 0 && is_upper))
                        res_A += (std::real(A[row + col * size_t(lda)]) * x[col * incx]);
                    else
                        res_A += (A[row + col * size_t(lda)] * x[col * incx]);
                }
                else if(row == k)
                {
                    // If main diagonal, assume 0 imaginary part.
                    if(is_upper)
                        res_A += (std::real(A[row + col * size_t(lda)]) * x[col * incx]);
                    else
                        res_A += (A[row + col * size_t(lda)] * x[col * incx]);
                }
            }
            else
            {
                // in the opposite triangle, get conjugate of value at transposed position
                rocblas_int trans_row = col;
                rocblas_int trans_col = ind;
                trans_row = is_upper ? trans_row + (k - trans_col) : trans_row - trans_col;
                if(trans_row <= k && trans_row >= 0)
                {
                    res_A += (conj(A[trans_row + trans_col * size_t(lda)]) * x[col * incx]);
                }
            }
        }
    }
    return res_A;
}

template <rocblas_int DIM_X, rocblas_int DIM_Y, typename T>
__device__ void rocblas_hbmvn_kernel_calc(bool        is_upper,
                                          rocblas_int n,
                                          rocblas_int k,
                                          T           alpha,
                                          const T*    A,
                                          int64_t     lda,
                                          const T*    x,
                                          int64_t     incx,
                                          T           beta,
                                          T*          y,
                                          int64_t     incy)
{
    rocblas_int  thread_id = threadIdx.x + threadIdx.y * blockDim.x;
    __shared__ T sdata[DIM_X * DIM_Y];

    if(alpha)
    {
        // threads are all configurated locally
        rocblas_int ty  = thread_id / DIM_X;
        rocblas_int tx  = thread_id % DIM_X;
        rocblas_int ind = blockIdx.x * DIM_X + tx;
        sdata[tx + ty * DIM_X]
            = rocblas_hbmvn_kernel_helper<DIM_Y>(ty, ind, is_upper, n, k, A, lda, x, incx);
        __syncthreads();
    }

    if(thread_id < DIM_X)
    {
        rocblas_int ind = blockIdx.x * DIM_X + thread_id;

        if(alpha)
        {
            for(rocblas_int i = 1; i < DIM_Y; i++)
                sdata[thread_id] += sdata[thread_id + DIM_X * i];

            if(ind < n)
                y[ind * incy] = beta ? alpha * sdata[thread_id] + beta * y[ind * incy]
                                     : alpha * sdata[thread_id];
        }
        else
        {
            if(ind < n)
                y[ind * incy] = beta ? y[ind * incy] * beta : 0;
        }
    }
}

__device__ void rocblas_hpmv_kernel_calc(bool        is_upper,
                                                         rocblas_int n,
                                                         T           alpha,
                                                         const T*    AP,
                                                         const T*    x,
                                                         int64_t     incx,
                                                         T           beta,
                                                         T*          y,
                                                         int64_t     incy)
{
    rocblas_int thread_id = threadIdx.x + threadIdx.y * DIM_X;

    // threads are all configurated locally
    rocblas_int tx = thread_id % DIM_X;
    rocblas_int ty = thread_id / DIM_X;

    rocblas_int ind = blockIdx.x * DIM_X + tx;

    if(!alpha)
    {
        if(thread_id < DIM_X && ind < n)
        {
            rocblas_int idx = blockIdx.x * DIM_X + thread_id;
            if(idx < n)
                y[idx * int64_t(incy)] = beta ? beta * y[idx * int64_t(incy)] : 0;
        }
        return;
    }

    __shared__ T sdata[DIM_X * DIM_Y];
    T            res_A = 0.0;
    rocblas_int  col;

    for(col = ty; col < n; col += DIM_Y)
    {
        if(ind < n)
        {
            int  ind_x = ind;
            int  ind_y = col;
            bool CONJ  = false;

            if((ind > col && is_upper) || (ind < col && !is_upper))
            {
                // in the opposite triangle, get conjugate of value at transposed position
                ind_x = col;
                ind_y = ind;
                CONJ  = true;
            }

            // The indices used here for AP come from the summation of the number of elements
            // in previous columns.
            //                              col
            // For upper matrices, index = sigma(i) + row.
            //                              i=1
            //
            //                              col-1
            // For lower matrices, index = sigma(n-i) + row
            //                              i=0

            int64_t index = is_upper
                                ? ((int64_t(ind_y) * (ind_y + 1)) / 2) + ind_x
                                : ((int64_t(ind_y) * (2 * n - ind_y + 1)) / 2) + (ind_x - ind_y);

            res_A += (ind_x == ind_y ? std::real(AP[index])
                      : CONJ         ? conj(AP[index])
                                     : (AP[index]))
                     * x[col * int64_t(incx)];
        }
    }

    // Store partial sums for the diagonal
    sdata[tx + ty * DIM_X] = res_A;
    __syncthreads();

    if(thread_id < DIM_X && ind < n)
    {
        // Add the partial sums of each diagonal and store
        for(rocblas_int i = 1; i < DIM_Y; i++)
            sdata[thread_id] += sdata[thread_id + DIM_X * i];

        int64_t idx = blockIdx.x * DIM_X + thread_id;
        // Update y.
        if(idx < n)
            y[idx * int64_t(incy)] = beta ? alpha * sdata[thread_id] + beta * y[idx * int64_t(incy)]
                                          : alpha * sdata[thread_id];
    }
}

__device__ void rocblas_hpr2_kernel_calc(bool        is_upper,
                                                         rocblas_int n,
                                                         T           alpha,
                                                         const T*    x,
                                                         int64_t     incx,
                                                         const T*    y,
                                                         int64_t     incy,
                                                         T*          AP)
{
    rocblas_int tx = (blockIdx.x * DIM_X * N_TX) + threadIdx.x;
    rocblas_int ty = blockIdx.y * DIM_Y + threadIdx.y;

    int index = is_upper ? ((ty * (ty + 1)) / 2) + tx : ((ty * (2 * n - ty + 1)) / 2) + (tx - ty);

#pragma unroll
    for(int i = 0; i < N_TX; i++, tx += DIM_X, index += DIM_X)
    {
        if(is_upper ? ty < n && tx < ty : tx < n && ty < tx)
        {
            AP[index] += alpha * x[tx * incx] * conj(y[ty * incy])
                         + conj(alpha) * y[tx * incy] * conj(x[ty * incx]);
        }
        else if(tx == ty && tx < n)
        {
            AP[index] = std::real(AP[index]) + alpha * x[tx * incx] * conj(y[ty * incy])
                        + conj(alpha) * y[tx * incy] * conj(x[ty * incx]);
        }
    }
}

__device__ void
    rocblas_hpr_kernel_calc(bool is_upper, rocblas_int n, U alpha, const T* x, int64_t incx, T* AP)
{
    int tx = (blockIdx.x * DIM_X * N_TX) + threadIdx.x;
    int ty = blockIdx.y * DIM_Y + threadIdx.y;

    int index = is_upper ? ((ty * (ty + 1)) / 2) + tx : ((ty * (2 * n - ty + 1)) / 2) + (tx - ty);

#pragma unroll
    for(int i = 0; i < N_TX; i++, tx += DIM_X, index += DIM_X)
    {
        if(is_upper ? ty < n && tx < ty : tx < n && ty < tx)
            AP[index] += alpha * x[tx * incx] * conj(x[ty * incx]);
        else if(tx == ty && tx < n)
        {
            AP[index] = std::real(AP[index]) + alpha * std::norm(x[tx * incx]);
        }
    }
}

__device__ T rocblas_sbmv_kernel_helper(rocblas_int ty,
                                               rocblas_int ind,
                                               rocblas_int n,
                                               rocblas_int k,
                                               const T* __restrict__ A,
                                               int64_t lda,
                                               const T* __restrict__ x,
                                               int64_t incx)
{
    T           res_A = 0.0;
    rocblas_int col;

    // Since the column is consistent, we iterate up diagonally in banded format
    // ty defines the column of banded matrix
    for(col = ty; col < n; col += DIM_Y)
    {
        // We have to convert ind to banded matrix row
        rocblas_int row = UPPER ? ind + (k - col) : ind - col;

        if(ind < n)
        {
            if((ind <= col && UPPER) || (ind >= col && !UPPER))
            {
                // in upper/lower triangular part
                if(row <= k && row >= 0)
                {
                    res_A += A[row + col * size_t(lda)] * x[col * incx];
                }
            }
            else
            {
                // in the opposite triangle, get value at transposed position
                rocblas_int trans_row = col;
                rocblas_int trans_col = ind;
                trans_row             = UPPER ? trans_row + (k - trans_col) : trans_row - trans_col;
                if(trans_row <= k && trans_row >= 0)
                {
                    res_A += A[trans_row + trans_col * size_t(lda)] * x[col * incx];
                }
            }
        }
    }
    return res_A;
}

__device__ void rocblas_sbmv_kernel_calc(rocblas_int n,
                                                rocblas_int k,
                                                T           alpha,
                                                const T* __restrict__ A,
                                                int64_t lda,
                                                const T* __restrict__ x,
                                                int64_t incx,
                                                T       beta,
                                                T* __restrict__ y,
                                                int64_t incy)
{
    rocblas_int thread_id = threadIdx.x + threadIdx.y * blockDim.x;

    if(!alpha)
    {
        rocblas_int ind = blockIdx.x * DIM_X + thread_id;
        if(thread_id < DIM_X && ind < n)
        {
            y[ind * incy] = beta ? (beta * y[ind * incy]) : 0;
        }
        return;
    }

    // threads are all configurated locally
    rocblas_int tx = thread_id % DIM_X;
    rocblas_int ty = thread_id / DIM_X;

    rocblas_int ind = blockIdx.x * DIM_X + tx;

    __shared__ T sdata[DIM_X * DIM_Y];

    T res_A;

    res_A = rocblas_sbmv_kernel_helper<UPPER, DIM_Y>(ty, ind, n, k, A, lda, x, incx);

    sdata[tx + ty * DIM_X] = res_A;

    __syncthreads();

    ind = blockIdx.x * DIM_X + thread_id;
    if(thread_id < DIM_X && ind < n)
    {
        for(rocblas_int i = 1; i < DIM_Y; i++)
            sdata[thread_id] += sdata[thread_id + DIM_X * i];

        y[ind * incy]
            = beta ? (alpha * sdata[thread_id]) + (beta * y[ind * incy]) : alpha * sdata[thread_id];
    }
}

template <rocblas_int DIM_X, rocblas_int DIM_Y, typename T>
__device__ void rocblas_spmv_kernel_calc(bool        is_upper,
                                         rocblas_int n,
                                         T           alpha,
                                         const T* __restrict__ AP,
                                         const T* __restrict__ x,
                                         int64_t incx,
                                         T       beta,
                                         T* __restrict__ y,
                                         int64_t incy)
{
    rocblas_int thread_id = threadIdx.x + threadIdx.y * blockDim.x;

    if(!alpha)
    {
        rocblas_int ind = blockIdx.x * DIM_X + thread_id;
        if(thread_id < DIM_X && ind < n)
        {
            y[ind * incy] = beta ? (beta * y[ind * incy]) : 0;
        }
        return;
    }

    // threads are all configurated locally
    rocblas_int tx = thread_id % DIM_X;
    rocblas_int ty = thread_id / DIM_X;

    rocblas_int ind = blockIdx.x * DIM_X + tx;

    __shared__ T sdata[DIM_X * DIM_Y];
    T            res_A = 0.0;
    rocblas_int  col;

    for(col = ty; col < n; col += DIM_Y)
    {
        if(ind < n)
        {
            int ind_x = ind;
            int ind_y = col;

            if((ind > col && is_upper) || (ind < col && !is_upper))
            {
                // in the opposite triangle, get transposed position
                ind_x = col;
                ind_y = ind;
            }

            // row, col to packed index
            size_t index = is_upper ? ((ind_y * (size_t(ind_y) + 1)) / 2) + ind_x
                                    : ((ind_y * (2 * size_t(n) - ind_y + 1)) / 2) + (ind_x - ind_y);

            res_A += AP[index] * x[col * incx];
        }
    }

    // Store partial sums
    sdata[tx + ty * DIM_X] = res_A;

    __syncthreads();

    ind = blockIdx.x * DIM_X + thread_id;
    if(thread_id < DIM_X && ind < n)
    {
        // Add the partial sums and store
        for(rocblas_int i = 1; i < DIM_Y; i++)
        {
            sdata[thread_id] += sdata[thread_id + DIM_X * i];
        }

        y[ind * incy]
            = beta ? (alpha * sdata[thread_id]) + (beta * y[ind * incy]) : alpha * sdata[thread_id];
    }
}

template <int DIM_X, int DIM_Y, int N_TX, typename T>
__device__ void rocblas_spr2_kernel_calc(bool        is_upper,
                                         rocblas_int n,
                                         T           alpha,
                                         const T*    x,
                                         int64_t     incx,
                                         const T*    y,
                                         int64_t     incy,
                                         T*          AP)
{
    rocblas_int tx = (blockIdx.x * DIM_X * N_TX) + threadIdx.x;
    rocblas_int ty = blockIdx.y * DIM_Y + threadIdx.y;

    int index = is_upper ? ((ty * (ty + 1)) / 2) + tx : ((ty * (2 * n - ty + 1)) / 2) + (tx - ty);

#pragma unroll
    for(int i = 0; i < N_TX; i++, tx += DIM_X, index += DIM_X)
    {
        if(is_upper ? ty < n && tx <= ty : tx < n && ty <= tx)
            AP[index] += alpha * x[tx * incx] * y[ty * incy] + alpha * y[tx * incy] * x[ty * incx];
    }
}

__device__ void
    rocblas_spr_kernel_calc(bool is_upper, rocblas_int n, T alpha, const T* x, int64_t incx, T* AP)
{
    int tx = (blockIdx.x * DIM_X * N_TX) + threadIdx.x;
    int ty = blockIdx.y * DIM_Y + threadIdx.y;

    int index = is_upper ? ((ty * (ty + 1)) / 2) + tx : ((ty * (2 * n - ty + 1)) / 2) + (tx - ty);

#pragma unroll
    for(int i = 0; i < N_TX; i++, tx += DIM_X, index += DIM_X)
    {
        if(is_upper ? ty < n && tx <= ty : tx < n && ty <= tx)
            AP[index] += alpha * x[tx * incx] * x[ty * incx];
    }
}

template <int DIM_X, int DIM_Y, int N_TX, typename T>
__device__ void rocblas_syr2_kernel_calc(bool     is_upper,
                                         int      n,
                                         T        alpha,
                                         const T* x,
                                         int64_t  incx,
                                         const T* y,
                                         int64_t  incy,
                                         T*       A,
                                         int64_t  lda)
{
    int tx = (blockIdx.x * DIM_X * N_TX) + threadIdx.x;
    int ty = blockIdx.y * DIM_Y + threadIdx.y;
#pragma unroll
    for(int i = 0; i < N_TX; i++, tx += DIM_X)
    {
        if(is_upper ? ty < n && tx <= ty : tx < n && ty <= tx)
            A[tx + ty * lda]
                += alpha * x[tx * incx] * y[ty * incy] + alpha * y[tx * incy] * x[ty * incx];
    }
}

template <rocblas_int DIM_Y, typename T>
__device__ T rocblas_tbmvn_kernel_helper(rocblas_int ty,
                                         rocblas_int ind,
                                         bool        is_upper,
                                         bool        is_unit_diag,
                                         rocblas_int n,
                                         rocblas_int k,
                                         const T*    A,
                                         int64_t     lda,
                                         const T*    w_x_copy)
{
    T           res_A = 0.0;
    rocblas_int col;

    // Since the column is consistent, we can iterate up the diagonal
    // ty defines the column of banded & regular matrix
    for(col = ty; col < n; col += DIM_Y)
    {
        // We have to convert ind to banded matrix row
        rocblas_int row = is_upper ? ind + (k - col) : ind - col;

        if(ind < n)
        {
            // Regular case, simply multiply
            if(row < k && row > 0)
            {
                res_A += (A[row + col * size_t(lda)] * w_x_copy[col]);
            }
            else if(row == 0)
            {
                // If main diagonal && diag, don't reference matrix, assume 1.
                if(is_unit_diag && (!is_upper || k == 0 && is_upper))
                    res_A += w_x_copy[col];
                else
                    res_A += (A[row + col * size_t(lda)] * w_x_copy[col]);
            }
            else if(row == k)
            {
                // If diag, don't reference matrix, assume 1.
                if(is_unit_diag && is_upper)
                    res_A += w_x_copy[col];
                else
                    res_A += (A[row + col * size_t(lda)] * w_x_copy[col]);
            }
        }
    }
    return res_A;
}

template <rocblas_int DIM_Y, typename T>
__device__ T rocblas_tbmvt_kernel_helper(bool        CONJ,
                                         rocblas_int ty,
                                         rocblas_int ind,
                                         bool        is_upper,
                                         bool        is_unit_diag,
                                         rocblas_int n,
                                         rocblas_int k,
                                         const T*    A,
                                         int64_t     lda,
                                         const T*    w_x_copy)
{
    T           res_A = 0.0;
    rocblas_int row;

    // for transpose case, ty defines the row
    for(row = ty; row < lda && row <= k; row += DIM_Y)
    {
        // We have to convert ind to banded matrix row
        rocblas_int col = ind;

        if(col < n)
        {
            if(is_upper)
            {
                // Regular case
                rocblas_int min_row = k - col;
                // cppcheck-suppress knownConditionTrueFalse
                if(row < k && row >= k - col && row != k)
                {
                    res_A += ((CONJ ? conj(A[row + col * size_t(lda)]) : A[row + col * size_t(lda)])
                              * w_x_copy[row - min_row]);
                }
                else if(row == k)
                {
                    // if main diagonal && diag then don't reference A, assume 1.
                    if(is_unit_diag)
                        res_A += w_x_copy[row - min_row];
                    else
                        res_A += ((CONJ ? conj(A[row + col * size_t(lda)])
                                        : A[row + col * size_t(lda)])
                                  * w_x_copy[row - min_row]);
                }
            }
            else
            {
                if(row <= k && row <= n - 1 - col && row > 0)
                {
                    res_A += ((CONJ ? conj(A[row + col * size_t(lda)]) : A[row + col * size_t(lda)])
                              * w_x_copy[row + col]);
                }
                else if(row == 0)
                {
                    if(is_unit_diag)
                        res_A += w_x_copy[row + col];
                    else
                        res_A += ((CONJ ? conj(A[row + col * size_t(lda)])
                                        : A[row + col * size_t(lda)])
                                  * w_x_copy[row + col]);
                }
            }
        }
    }
    return res_A;
}

__device__ void ActivationFunction_PassThru(T (&__restrict__ res)[N],
                                                            const T (&__restrict__ data)[N],
                                                            const T /*gamma*/,
                                                            const T /*beta*/,
                                                            const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = data[i];
    }
}

__device__ void ActivationFunction_ReLU(T (&__restrict__ res)[N],
                                                        const T (&__restrict__ data)[N],
                                                        const T /*gamma*/,
                                                        const T /*beta*/,
                                                        const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = data[i] * (data[i] > 0);
    }
}

__device__ void ActivationFunction_Sigmoid(T (&__restrict__ res)[N],
                                                           const T (&__restrict__ data)[N],
                                                           const T /*gamma*/,
                                                           const T /*beta*/,
                                                           const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        // y = 1/(1 + exp(-x))
        res[i] = static_cast<T>(1) / (static_cast<T>(1) + exp(-data[i]));
    }
}

__device__ void ActivationFunction_TanH(T (&__restrict__ res)[N],
                                                        const T (&__restrict__ data)[N],
                                                        const T /*gamma*/,
                                                        const T beta,
                                                        const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        // y = beta * tanh(alpha * x)
        res[i] = beta * tanh(alpha * data[i]);
    }
}

__device__ void ActivationFunction_Abs(T (&__restrict__ res)[N],
                                                       const T (&__restrict__ data)[N],
                                                       const T /*gamma*/,
                                                       const T /*beta*/,
                                                       const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = fabs(data[i]);
    }
}

__device__ void ActivationFunction_Square(T (&__restrict__ res)[N],
                                                          const T (&__restrict__ data)[N],
                                                          const T /*gamma*/,
                                                          const T /*beta*/,
                                                          const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = data[i] * data[i];
    }
}

__device__ void ActivationFunction_Sqrt(T (&__restrict__ res)[N],
                                                        const T (&__restrict__ data)[N],
                                                        const T /*gamma*/,
                                                        const T /*beta*/,
                                                        const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = sqrt(data[i]);
    }
}

__device__ void ActivationFunction_Linear(T (&__restrict__ res)[N],
                                                          const T (&__restrict__ data)[N],
                                                          const T /*gamma*/,
                                                          const T beta,
                                                          const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = alpha + beta * data[i];
    }
}

__device__ void ActivationFunction_Power(T (&__restrict__ res)[N],
                                                         const T (&__restrict__ data)[N],
                                                         const T gamma,
                                                         const T beta,
                                                         const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        // y = (alpha + beta * x ) ^ gamma
        T arg  = alpha + data[i] * beta;
        res[i] = arg <= static_cast<T>(EPSILON) ? static_cast<T>(0) : pow(arg, gamma);
    }
}

__device__ void ActivationFunction_BNLL(T (&__restrict__ res)[N],
                                                        const T (&__restrict__ data)[N],
                                                        const T /*gamma*/,
                                                        const T /*beta*/,
                                                        const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        //	y = log(1 + exp(x))
        res[i] = (data[i] > 0) ? (data[i] + log(static_cast<T>(1) + exp(-data[i])))
                               : log(static_cast<T>(1) + exp(data[i]));
    }
}

__device__ void ActivationFunction_Leaky_ReLU(T (&__restrict__ res)[N],
                                                              const T (&__restrict__ data)[N],
                                                              const T /*gamma*/,
                                                              const T /*beta*/,
                                                              const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = data[i] * ((data[i] > 0) ? static_cast<T>(1) : alpha);
    }
}

__device__ void ActivationFunction_Clipped_ReLU(T (&__restrict__ res)[N],
                                                                const T (&__restrict__ data)[N],
                                                                const T /*gamma*/,
                                                                const T /*beta*/,
                                                                const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = fmin(static_cast<T>(alpha), fmax(static_cast<T>(data[i]), 0));
    }
}

__device__ void ActivationFunction_ELU(T (&__restrict__ res)[N],
                                                       const T (&__restrict__ data)[N],
                                                       const T /*gamma*/,
                                                       const T /*beta*/,
                                                       const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        res[i] = (data[i] > 0) ? data[i] : (alpha * (exp(data[i]) - static_cast<T>(1)));
    }
}

__device__ void ActivationFunction(T (&__restrict__ res)[N],
                                                   const T (&__restrict__ data)[N],
                                                   const T gamma,
                                                   const T beta,
                                                   const T alpha)
{
    static_assert(N <= 4);
    if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_PASTHRU)
    {
        ActivationFunction_PassThru(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_LOGISTIC)
    {
        ActivationFunction_Sigmoid(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_TANH)
    {
        ActivationFunction_TanH(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_RELU)
    {
        ActivationFunction_ReLU(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_SOFTRELU)
    {
        ActivationFunction_BNLL(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_ABS)
    {
        ActivationFunction_Abs(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_POWER)
    {
        ActivationFunction_Power(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_CLIPPED_RELU)
    {
        ActivationFunction_Clipped_ReLU(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_LEAKY_RELU)
    {
        ActivationFunction_Leaky_ReLU(res, data, gamma, beta, alpha);
    }
    else if constexpr(MIOPEN_NRN_OP_ID == MIOPEN_NEURON_ELU)
    {
        ActivationFunction_ELU(res, data, gamma, beta, alpha);
    }
}

