__device__ void ActivationFunction_ReLU_Diff(T (&__restrict__ bot_diff)[N],
                                                             const T (&__restrict__ top_diff)[N],
                                                             const T (&__restrict__ bot_data)[N],
                                                             const T* /*top_data*/,
                                                             const T /*diff_scale*/,
                                                             const T /*gamma*/,
                                                             const T /*beta*/,
                                                             const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        bot_diff[i] = top_diff[i] * (bot_data[i] > 0);
    }
}

__device__ void ActivationFunction_TanH_Diff(T (&__restrict__ bot_diff)[N],
                                                             const T (&__restrict__ top_diff)[N],
                                                             const T* /*bot_data*/,
                                                             const T (&__restrict__ top_data)[N],
                                                             const T /*diff_scale*/,
                                                             const T /*gamma*/,
                                                             const T beta,
                                                             const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        // dy/dx = alpha * (beta - y^2 / beta)
        T y         = top_data[i];
        bot_diff[i] = fabs(beta) <= static_cast<T>(EPSILON)
                          ? static_cast<T>(0)
                          : (top_diff[i] * alpha * (beta - y * y / beta));
    }
}

__device__ void ActivationFunction_Sigmoid_Diff(T (&__restrict__ bot_diff)[N],
                                                                const T (&__restrict__ top_diff)[N],
                                                                const T* /*bot_data*/,
                                                                const T (&__restrict__ top_data)[N],
                                                                const T /*diff_scale*/,
                                                                const T /*gamma*/,
                                                                const T /*beta*/,
                                                                const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        // y = 1/(1 + exp(-x))
        T sigmoid_x = top_data[i];
        bot_diff[i] = top_diff[i] * sigmoid_x * (static_cast<T>(1) - sigmoid_x);
    }
}

__device__ void ActivationFunction_Abs_Diff(T (&__restrict__ bot_diff)[N],
                                                            const T (&__restrict__ top_diff)[N],
                                                            const T (&__restrict__ bot_data)[N],
                                                            const T* /*top_data*/,
                                                            const T /*diff_scale*/,
                                                            const T /*gamma*/,
                                                            const T /*beta*/,
                                                            const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        bot_diff[i] = top_diff[i] * ((bot_data[i] > 0) ? 1 : -1);
    }
}

__device__ void ActivationFunction_Power_Diff(T (&__restrict__ bot_diff)[N],
                                                              const T* /*top_diff*/,
                                                              const T (&__restrict__ bot_data)[N],
                                                              const T (&__restrict__ top_data)[N],
                                                              const T diff_scale,
                                                              const T /*gamma*/,
                                                              const T beta,
                                                              const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        T arg = alpha + bot_data[i] * beta;
        bot_diff[i] =
            arg <= static_cast<T>(EPSILON) ? static_cast<T>(0) : (diff_scale * top_data[i] / arg);
    }
}

__device__ void ActivationFunction_BNLL_Diff(T (&__restrict__ bot_diff)[N],
                                                             const T (&__restrict__ top_diff)[N],
                                                             const T (&__restrict__ bot_data)[N],
                                                             const T* /*top_data*/,
                                                             const T /*diff_scale*/,
                                                             const T /*gamma*/,
                                                             const T /*beta*/,
                                                             const T /*alpha*/)
{
    for(uint i = 0; i < N; ++i)
    {
        // y = (log(1 + exp(x)))
        // dy/dx = 1/ (1 + exp(-x))
        T expval    = exp(fmin(static_cast<T>(bot_data[i]), static_cast<T>(kBNLL_THRESHOLD)));
        bot_diff[i] = top_diff[i] * expval / (expval + static_cast<T>(1));
    }
}

