            math::max(0, InLeftPads{}[1] - ConvDilationH * (YTilda - 1)), ConvStrides{}[1]);
        constexpr index_t iWTildaLeft = math::integer_divide_floor(
            math::max(0, InLeftPads{}[2] - ConvDilationW * (XTilda - 1)), ConvStrides{}[2]);

