            HTilda, math::integer_divide_ceil(InLeftPads{}[1] + Hi - 1, ConvStrides{}[1]) + 1);
        constexpr index_t iWTildaRight = math::min(
            WTilda, math::integer_divide_ceil(InLeftPads{}[2] + Wi - 1, ConvStrides{}[2]) + 1);

