        {
            p_c_thread.s.x.l =
                XdlopsGemm.template Run<M, N, K>(p_a_block, p_b_block, p_c_thread.s.x.l);
            p_c_thread.s.y.l = XdlopsGemm.template Run<M, N, K>(
                p_a_block, p_b_block + NPerXdlops, p_c_thread.s.y.l);

