__device__ void AdamInternal(T1* param_in,
                                    T1* param_out,
                                    T1* exp_avg_in,
                                    T1* exp_avg_out,
                                    T1* exp_avg_sq_in,
                                    T1* exp_avg_sq_out,
                                    T1* max_exp_avg_sq_in,
                                    T1* max_exp_avg_sq_out,
                                    T2 grad,
                                    T2 lr,
                                    T2 beta1,
                                    T2 beta2,
                                    T2 weight_decay,
                                    T2 eps,
                                    uint32_t step,
                                    bool amsgrad,
                                    bool maximize,
                                    bool adamw,
                                    size_t gid)
{
    T2 param      = static_cast<T2>(param_in[gid]);
    T2 exp_avg    = static_cast<T2>(exp_avg_in[gid]);
    T2 exp_avg_sq = static_cast<T2>(exp_avg_sq_in[gid]);

    __builtin_assume(exp_avg_sq >= 0 && exp_avg_sq <= 1);
    __builtin_assume(beta1 >= 0);
    __builtin_assume(beta2 >= 0);

    T2 bias_correction1 = 1 - pow(beta1, step);
    T2 bias_correction2 = 1 - pow(beta2, step);

    if(maximize)
        grad = -grad;

#ifdef __clang__
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wfloat-equal"
#endif

    if(weight_decay != 0)
    {
        if(adamw)
            param -= lr * weight_decay * param;
        else
            grad += param * weight_decay;
    }

#ifdef __clang__
#pragma clang diagnostic pop
#endif

    exp_avg    = exp_avg * beta1 + grad * (1 - beta1);
    exp_avg_sq = exp_avg_sq * beta2 + grad * grad * (1 - beta2);

    T2 denom;
    if(amsgrad)
    {
        T2 max_exp_avg_sq = static_cast<T2>(max_exp_avg_sq_in[gid]);
        __builtin_assume(max_exp_avg_sq >= 0 && max_exp_avg_sq <= 1);
        max_exp_avg_sq          = max(max_exp_avg_sq, exp_avg_sq);
        max_exp_avg_sq_out[gid] = static_cast<T1>(max_exp_avg_sq);
        denom                   = sqrt(max_exp_avg_sq) / sqrt(bias_correction2) + eps;
    }
    else
    {
        denom = sqrt(exp_avg_sq) / sqrt(bias_correction2) + eps;
    }

    T2 step_size = lr / bias_correction1;
    param        = param - step_size * exp_avg / denom;

    param_out[gid]      = static_cast<T1>(param);
    exp_avg_out[gid]    = static_cast<T1>(exp_avg);
    exp_avg_sq_out[gid] = static_cast<T1>(exp_avg_sq);
}

__device__ void AmpAdamSetOutputFromInput(T1* param_in,
                                                 T1* param_out,
                                                 half* param_out_fp16,
                                                 T1* exp_avg_in,
                                                 T1* exp_avg_out,
                                                 T1* exp_avg_sq_in,
                                                 T1* exp_avg_sq_out,
                                                 T1* max_exp_avg_sq_in,
                                                 T1* max_exp_avg_sq_out,
                                                 bool amsgrad,
                                                 size_t input_size)
{
    size_t gid = blockIdx.x * blockDim.x + threadIdx.x;
    size_t gsz = gridDim.x * blockDim.x;

    for(; gid < input_size; gid += gsz)
    {
        if(param_in != param_out)
            param_out[gid] = param_in[gid];
        if(param_out_fp16)
            param_out_fp16[gid] = static_cast<half>(param_in[gid]);
        if(exp_avg_in != exp_avg_out)
            exp_avg_out[gid] = exp_avg_in[gid];
        if(exp_avg_sq_in != exp_avg_sq_out)
            exp_avg_sq_out[gid] = exp_avg_sq_in[gid];
        if(amsgrad && max_exp_avg_sq_in != max_exp_avg_sq_out)
            max_exp_avg_sq_out[gid] = max_exp_avg_sq_in[gid];
    }
}

__global__ void AdamUpdateStep(bool* found_inf, int* step_in, int* step_out)
{
    size_t gid = blockIdx.x * blockDim.x + threadIdx.x;

    if(gid != 0)
        return;

    if(found_inf && *found_inf)
    {
        if(step_in != step_out)
            *step_out = *step_in;
        return;
    }

    *step_out = *step_in + 1;
}

__device__ void TransformersAdamWInternal(T1* param_in,
                                                 T1* param_out,
                                                 T1* exp_avg_in,
                                                 T1* exp_avg_out,
                                                 T1* exp_avg_sq_in,
                                                 T1* exp_avg_sq_out,
                                                 T2 grad,
                                                 T2 beta1,
                                                 T2 beta2,
                                                 T2 eps,
                                                 T2 lr_weight_decay,
                                                 T2 step_size,
                                                 size_t gid)
{
    T2 param      = static_cast<T2>(param_in[gid]);
    T2 exp_avg    = static_cast<T2>(exp_avg_in[gid]);
    T2 exp_avg_sq = static_cast<T2>(exp_avg_sq_in[gid]);

    __builtin_assume(exp_avg_sq >= 0 && exp_avg_sq <= 1);
    __builtin_assume(beta1 >= 0);
    __builtin_assume(beta2 >= 0);

    exp_avg    = exp_avg * beta1 + grad * (1 - beta1);
    exp_avg_sq = exp_avg_sq * beta2 + grad * grad * (1 - beta2);

    T2 denom = sqrt(exp_avg_sq) + eps;

    param = param - step_size * exp_avg / denom;
    param = param - param * lr_weight_decay;

    param_out[gid]      = static_cast<T1>(param);
    exp_avg_out[gid]    = static_cast<T1>(exp_avg);
    exp_avg_sq_out[gid] = static_cast<T1>(exp_avg_sq);
}

__global__ void TransformersAmpAdamWContiguous(PTYPE* param_in,
                                                          PTYPE* param_out,
                                                          half* param_out_fp16,
                                                          GTYPE* grad_in,
                                                          PTYPE* exp_avg_in,
                                                          PTYPE* exp_avg_out,
                                                          PTYPE* exp_avg_sq_in,
                                                          PTYPE* exp_avg_sq_out,
                                                          int32_t* grad_scale,
                                                          bool* found_inf,
                                                          float beta1,
                                                          float beta2,
                                                          float eps,
                                                          float lr_weight_decay,
                                                          float step_size,
                                                          size_t input_size)
{
    size_t gid = blockIdx.x * blockDim.x + threadIdx.x;

    if(gid >= input_size)
        return;

    if(found_inf == nullptr || *found_inf == false)
    {
        size_t gsz         = gridDim.x * blockDim.x;
        CTYPE scale_factor = (grad_scale) ? static_cast<CTYPE>(*grad_scale) : 1.0f;

        for(; gid < input_size; gid += gsz)
        {
            CTYPE grad = static_cast<CTYPE>(grad_in[gid]);
            if(grad_scale)
                grad /= scale_factor;

            TransformersAdamWInternal<PTYPE, CTYPE>(param_in,
                                                    param_out,
                                                    exp_avg_in,
                                                    exp_avg_out,
                                                    exp_avg_sq_in,
                                                    exp_avg_sq_out,
                                                    grad,
                                                    beta1,
                                                    beta2,
                                                    eps,
                                                    lr_weight_decay,
                                                    step_size,
                                                    gid);

            if(param_out_fp16)
                param_out_fp16[gid] = static_cast<half>(param_out[gid]);
        }
    }
    else
    {
        AmpAdamSetOutputFromInput<PTYPE>(param_in,
                                         param_out,
                                         param_out_fp16,
                                         exp_avg_in,
                                         exp_avg_out,
                                         exp_avg_sq_in,
                                         exp_avg_sq_out,
                                         nullptr,
                                         nullptr,
                                         false,
                                         input_size);
    }
}

__global__ void TransformersAmpAdamWContiguousWithStep(PTYPE* param_in,
                                                                  PTYPE* param_out,
                                                                  half* param_out_fp16,
                                                                  GTYPE* grad_in,
                                                                  PTYPE* exp_avg_in,
                                                                  PTYPE* exp_avg_out,
                                                                  PTYPE* exp_avg_sq_in,
                                                                  PTYPE* exp_avg_sq_out,
                                                                  int32_t* grad_scale,
                                                                  bool* found_inf,
                                                                  int* step,
                                                                  float lr,
                                                                  float beta1,
                                                                  float beta2,
                                                                  float eps,
                                                                  float lr_weight_decay,
                                                                  float step_size,
                                                                  bool correct_bias,
                                                                  size_t input_size)
{
    size_t gid = blockIdx.x * blockDim.x + threadIdx.x;

    if(gid >= input_size)
        return;

    if(found_inf == nullptr || *found_inf == false)
    {
        size_t gsz         = gridDim.x * blockDim.x;
        CTYPE scale_factor = (grad_scale) ? static_cast<CTYPE>(*grad_scale) : 1.0f;
        uint32_t step_val  = static_cast<uint32_t>(*step) + 1;

        if(step_size < 0)
        {
            if(correct_bias)
            {
                CTYPE bias_correction1 = 1 - pow(beta1, step_val);
                CTYPE bias_correction2 = 1 - pow(beta2, step_val);
                step_size              = lr * sqrt(bias_correction2) / bias_correction1;
            }
            else
            {
                step_size = lr;
            }
        }

        for(; gid < input_size; gid += gsz)
        {
            CTYPE grad = static_cast<CTYPE>(grad_in[gid]);
            if(grad_scale)
                grad /= scale_factor;

            TransformersAdamWInternal<PTYPE, CTYPE>(param_in,
                                                    param_out,
                                                    exp_avg_in,
                                                    exp_avg_out,
                                                    exp_avg_sq_in,
                                                    exp_avg_sq_out,
                                                    grad,
                                                    beta1,
                                                    beta2,
                                                    eps,
                                                    lr_weight_decay,
                                                    step_size,
                                                    gid);
            if(param_out_fp16)
                param_out_fp16[gid] = static_cast<half>(param_out[gid]);
        }
    }
    else
    {
        AmpAdamSetOutputFromInput<PTYPE>(param_in,
                                         param_out,
                                         param_out_fp16,
                                         exp_avg_in,
                                         exp_avg_out,
                                         exp_avg_sq_in,
                                         exp_avg_sq_out,
                                         nullptr,
                                         nullptr,
                                         false,
                                         input_size);
    }
}

__global__ void __launch_bounds__(MIO_BN_GRP0* MIO_BN_GRP1* MIO_BN_GRP2)
    MIOpenBatchNormActivInferSpatialEstHIP(const FP_TYPE_PREC alpha,
                                           const FP_TYPE_PREC beta,
                                           const FP_TYPE_PREC gamma,
                                           const double epsilon,
                                           const FP_TYPE* __restrict in,
                                           FP_TYPE* __restrict out,
                                           const FP_TYPE_PREC* __restrict bias,
                                           const FP_TYPE_PREC* __restrict scale,
                                           const FP_TYPE_PREC* __restrict estimatedMean,
                                           const FP_TYPE_PREC* __restrict estimatedVariance)
{
    unsigned int tidx = blockIdx.x * blockDim.x + threadIdx.x;
    // HIP runtime does not support launching non-uniform blocks
    // So extra threads are launched to handle this.
    if(tidx >= MIOPEN_SBN_BOUNDS)
        return;

    unsigned int tidy = blockIdx.y * blockDim.y + threadIdx.y;

    unsigned int c_i      = tidy;
    unsigned int hw_i     = tidx;
    unsigned int c_offset = c_i * MIO_BN_HW;

    // Load the mean, variance, scale, and bias that is broadcast across the block
    const FP_TYPE_PREC pmean       = estimatedMean[c_i];
    const FP_TYPE_PREC pvar        = estimatedVariance[c_i];
    const FP_TYPE_PREC pscale      = scale[c_i];
    const FP_TYPE_PREC pbias       = bias[c_i];
    const FP_TYPE_PREC invVariance = rsqrt(pvar + epsilon);
    // Load the input data. This is done in a vectorized manner
    FP_TYPE data[MIOPEN_READ_UNIT];

#pragma unroll 2
    for(unsigned int n_i = 0; n_i < MIO_BN_N; n_i++)
    {
        const unsigned int index = n_i * MIO_BN_CHW + c_offset + hw_i * MIOPEN_READ_UNIT;
        // Perform a vectorized load of the input data
        *(reinterpret_cast<MIOPEN_READ_TYPE*>(data)) =
            *(reinterpret_cast<const MIOPEN_READ_TYPE*>(in + index));
        FP_TYPE_PREC bnRes[MIOPEN_READ_UNIT];
        FP_TYPE_PREC actRes[MIOPEN_READ_UNIT];
#pragma unroll
        for(unsigned int i = 0; i < MIOPEN_READ_UNIT; ++i)
        {
            bnRes[i] =
                fma(pscale, (static_cast<FP_TYPE_PREC>(data[i]) - pmean) * invVariance, pbias);
        }
        ActivationFunction(actRes, bnRes, gamma, beta, alpha);
        if constexpr(MIOPEN_USE_FP16)
        {
#pragma unroll
            for(unsigned int i = 0; i < MIOPEN_READ_UNIT; i++)
            {
                out[index + i] = static_cast<FP_TYPE>(actRes[i]);
            }
        }
        else
        {
            // perform a vectorized store of the output data as FP_TYPE and PF_TYPE_PREC are same
            // for FP32
            *(reinterpret_cast<MIOPEN_READ_TYPE*>(out + index)) =
                *(reinterpret_cast<const MIOPEN_READ_TYPE*>(actRes));
        }
    }
}

__global__ void __launch_bounds__(MIO_BN_GRP0* MIO_BN_GRP1* MIO_BN_GRP2)
    MIOpenBatchNormActivInferPerActEstHIP(const FP_TYPE_PREC alpha,
                                          const FP_TYPE_PREC beta,
                                          const FP_TYPE_PREC gamma,
                                          const double epsilon,
                                          const FP_TYPE* __restrict in,
                                          FP_TYPE* __restrict out,
                                          const FP_TYPE_PREC* __restrict bias,
                                          const FP_TYPE_PREC* __restrict scale,
                                          const FP_TYPE_PREC* __restrict estimatedMean,
                                          const FP_TYPE_PREC* __restrict estimatedVariance)
{
    unsigned int tidx = blockIdx.x * blockDim.x + threadIdx.x;
    // HIP runtime does not support launching non-uniform blocks
    // So extra threads are launched to handle this.
    if(tidx >= MIOPEN_SBN_BOUNDS)
        return;

    unsigned int chw_i = tidx * MIOPEN_READ_UNIT;

    FP_TYPE_PREC pmean[MIOPEN_READ_UNIT];
    FP_TYPE_PREC pvar[MIOPEN_READ_UNIT];
    FP_TYPE_PREC pscale[MIOPEN_READ_UNIT];
    FP_TYPE_PREC pbias[MIOPEN_READ_UNIT];

    // Perform a vectorized load of the mean, variance, scale, and bias
    *(reinterpret_cast<MIOPEN_PREC_READ_TYPE*>(pmean)) =
        *(reinterpret_cast<const MIOPEN_PREC_READ_TYPE*>(estimatedMean + chw_i));
    *(reinterpret_cast<MIOPEN_PREC_READ_TYPE*>(pvar)) =
        *(reinterpret_cast<const MIOPEN_PREC_READ_TYPE*>(estimatedVariance + chw_i));
    *(reinterpret_cast<MIOPEN_PREC_READ_TYPE*>(pscale)) =
        *(reinterpret_cast<const MIOPEN_PREC_READ_TYPE*>(scale + chw_i));
    *(reinterpret_cast<MIOPEN_PREC_READ_TYPE*>(pbias)) =
        *(reinterpret_cast<const MIOPEN_PREC_READ_TYPE*>(bias + chw_i));

    FP_TYPE data[MIOPEN_READ_UNIT];
    FP_TYPE_PREC invVariance[MIOPEN_READ_UNIT];

#pragma unroll
    for(unsigned int i = 0; i < MIOPEN_READ_UNIT; i++)
        invVariance[i] = rsqrt(pvar[i] + epsilon);

#pragma unroll 2
    for(unsigned int n_i = 0; n_i < MIO_BN_N; n_i++)
    {
        const unsigned int index = n_i * MIO_BN_CHW + chw_i;
        // Perform a vectorized load of the input data
        *(reinterpret_cast<MIOPEN_READ_TYPE*>(data)) =
            *(reinterpret_cast<const MIOPEN_READ_TYPE*>(in + index));
        FP_TYPE_PREC bnRes[MIOPEN_READ_UNIT];
        FP_TYPE_PREC actRes[MIOPEN_READ_UNIT];
#pragma unroll
        for(unsigned int i = 0; i < MIOPEN_READ_UNIT; ++i)
        {
            bnRes[i] = fma(pscale[i],
                           (static_cast<FP_TYPE_PREC>(data[i]) - pmean[i]) * invVariance[i],
                           pbias[i]);
        }

        ActivationFunction(actRes, bnRes, gamma, beta, alpha);
        if constexpr(MIOPEN_USE_FP16)
        { // In this situation, FP_TYPE_PREC is FP32 whereas FP_TYPE is FP16
          // So, we cannot perform a vectorized store
#pragma unroll
            for(unsigned int i = 0; i < MIOPEN_READ_UNIT; i++)
            {
                out[index + i] = static_cast<FP_TYPE>(actRes[i]);
            }
        }
        else
        {
            // perform a vectorized store of the output data as FP_TYPE and PF_TYPE_PREC are same
            *(reinterpret_cast<MIOPEN_READ_TYPE*>(out + index)) =
                *(reinterpret_cast<const MIOPEN_READ_TYPE*>(actRes));
        }
    }
}

input:
__device__ char* cat_copy_buf(const char* __restrict__ input,
                              char* __restrict__ output,
                              const size_t input_dim_size,
                              const size_t stride)

output:
__device__ char* cat_copy_buf(const char* __restrict__ input,
                              char* __restrict__ output,
                              const size_t input_dim_size,
                              const size_t stride)
{
    if(!input)
        return output;

    size_t gid0 = blockIdx.x * blockDim.x + threadIdx.x;
    size_t gid1 = blockIdx.y * blockDim.y + threadIdx.y;
    size_t gsz0 = gridDim.x * blockDim.x;
    size_t end  = input_dim_size * stride;
    size_t step = gsz0 * sizeof(ushort4);

    input += gid1 * end;

    size_t i = gid0 * sizeof(ushort4);
    for(; (i + sizeof(ushort4)) <= end; i += step)
        *reinterpret_cast<ushort4*>(output + i) = *reinterpret_cast<const ushort4*>(input + i);

    if((i + sizeof(ushort2)) <= end)
    {
        *reinterpret_cast<ushort2*>(output + i) = *reinterpret_cast<const ushort2*>(input + i);
        i += sizeof(ushort2);
    }

    if(i < end)
        *reinterpret_cast<ushort1*>(output + i) = *reinterpret_cast<const ushort1*>(input + i);

    return output + end;
}

__global__ void Cat8FwdPacked(const char* __restrict__ input1,
                                         const char* __restrict__ input2,
                                         const char* __restrict__ input3,
                                         const char* __restrict__ input4,
                                         const char* __restrict__ input5,
                                         const char* __restrict__ input6,
                                         const char* __restrict__ input7,
                                         const char* __restrict__ input8,
                                         char* __restrict__ output,
                                         const size_t input1_dim_size,
                                         const size_t input2_dim_size,
                                         const size_t input3_dim_size,
                                         const size_t input4_dim_size,
                                         const size_t input5_dim_size,
                                         const size_t input6_dim_size,
                                         const size_t input7_dim_size,
                                         const size_t input8_dim_size,
                                         const size_t outer_size,
                                         const size_t stride,
                                         const size_t output_dim_size)
{
    size_t gid = blockIdx.y * blockDim.y + threadIdx.y;

    if(gid >= outer_size)
        return;

    output += gid * output_dim_size * stride;

    output = cat_copy_buf(input1, output, input1_dim_size, stride);
    output = cat_copy_buf(input2, output, input2_dim_size, stride);
    output = cat_copy_buf(input3, output, input3_dim_size, stride);
    output = cat_copy_buf(input4, output, input4_dim_size, stride);
    output = cat_copy_buf(input5, output, input5_dim_size, stride);
    output = cat_copy_buf(input6, output, input6_dim_size, stride);
    output = cat_copy_buf(input7, output, input7_dim_size, stride);
    cat_copy_buf(input8, output, input8_dim_size, stride);
}

