__device__ void thread_redux(Numerics* stats, size_t wid)
{
    const auto lid = threadIdx.x;
    if(lid < wid)
    {
        stats[lid].sum += stats[lid + wid].sum;
        stats[lid].absSum += stats[lid + wid].absSum;
        stats[lid].min = fmin(stats[lid].min, stats[lid + wid].min);
        stats[lid].max = fmax(stats[lid].max, stats[lid + wid].max);
    }
}

template <typename T, typename U>
__device__ void
check_numerics(const T* C_d, size_t sz, CheckNumericsResult* abnormal, bool computeStats)
{
    __shared__ Numerics stats[256];
    U sum    = 0;
    U absSum = 0;
    T minV   = std::numeric_limits<T>::max();
    T maxV   = std::numeric_limits<T>::min();

    size_t offset = (blockIdx.x * blockDim.x + threadIdx.x);
    size_t stride = blockDim.x * gridDim.x;

    for(size_t i = offset; i < sz; i += stride)
    {
        T val = C_d[i];
        sum += static_cast<U>(val);
        const auto abs_val = fabs(static_cast<U>(val));
        absSum += abs_val;
        minV = min(minV, val);
        maxV = max(maxV, val);
        if(abs_val <= static_cast<U>(0.0f))
            abnormal->hasZero = 1;
        if(isnan(static_cast<U>(val)))
            abnormal->hasNan = 1;
        if(isinf(static_cast<U>(val)))
            abnormal->hasInf = 1;
    }
    if(computeStats)
    {
        stats[threadIdx.x].sum    = static_cast<float>(sum);
        stats[threadIdx.x].absSum = static_cast<float>(absSum);
        stats[threadIdx.x].min    = static_cast<float>(minV);
        stats[threadIdx.x].max    = static_cast<float>(maxV);
        __syncthreads();
        for(int idx = 128; idx > 0; idx = idx >> 1)
        {
            thread_redux(stats, idx);
            __syncthreads();
        }
        if(threadIdx.x == 0)
        {
            atomicAdd(&abnormal->n.sum, stats[0].sum);
            atomicAdd(&abnormal->n.absSum, stats[0].absSum);
            atomicMin(&abnormal->n.min, stats[0].min);
            atomicMax(&abnormal->n.max, stats[0].max);
        }
    }
}

__global__ void check_numerics_fp32(const void* __restrict__ C_d,
                                               size_t sz,
                                               CheckNumericsResult* __restrict__ abnormal,
                                               bool computeStats)
{
    check_numerics<float, float>(reinterpret_cast<const float*>(C_d), sz, abnormal, computeStats);
}

__global__ void check_numerics_fp16(const void* __restrict__ C_d,
                                               size_t sz,
                                               CheckNumericsResult* __restrict__ abnormal,
                                               bool computeStats)
{
    check_numerics<_Float16, float>(
        reinterpret_cast<const _Float16*>(C_d), sz, abnormal, computeStats);
}

__global__ void check_numerics_bf16(const void* __restrict__ C_d,
                                               size_t sz,
                                               CheckNumericsResult* __restrict__ abnormal,
                                               bool computeStats)
{
    check_numerics<hip_bfloat16, float>(
        reinterpret_cast<const hip_bfloat16*>(C_d), sz, abnormal, computeStats);
}

__global__ void
InitKernelStateHIP(rocrand_state_xorwow* state, ulong prng_seed, ulong states_num)
{
    // Get the index of the current element
    size_t index  = blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = blockDim.x * gridDim.x;

    for(size_t gid = index; gid < states_num; gid += stride)
    {
        rocrand_state_xorwow state_gid;
        rocrand_init(prng_seed, gid, 0ULL, &state_gid);
        state[gid] = state_gid;
    }
}

__device__ void dropout_kernel(const rocrand_state_xorwow* state,
                                               float dropout,
                                               float scale,
                                               D dim1,
                                               D dim2,
                                               D dim3,
                                               D dim4,
                                               F* y,
                                               D out_str0,
                                               D out_str1,
                                               D out_str2,
                                               D out_str3,
                                               const F* x,
                                               D in_str0,
                                               D in_str1,
                                               D in_str2,
                                               D in_str3,
                                               uchar* reserveSpace,
                                               D total_work,
                                               uint64_t in_offset,
                                               uint64_t out_offset,
                                               uint64_t rsvsp_offset)
{
    F dat_blk[RD_BLCK];     // Register space to read the input data
    uchar is_kept[RD_BLCK]; // Register space to store the mask for the dropout

    auto sid = threadIdx.x + blockIdx.x * blockDim.x;
    rocrand_state_xorwow cur_state; // Read the state of the current thread
    cur_state = state[sid];

    for(auto gid = threadIdx.x + blockIdx.x * blockDim.x; gid < total_work;
        gid += blockDim.x * gridDim.x)
    {
        auto i0    = gid / (dim1 * dim2 * dim3 * dim4);
        auto i1    = (gid / (dim2 * dim3 * dim4)) % dim1;
        auto i2    = (gid / (dim3 * dim4)) % dim2;
        auto i3    = (gid / dim4) % dim3;
        auto i4    = gid % dim4;
        auto i4_rd = i4 / RD_BLCK;

        auto x_idx = i0 * in_str0 + i1 * in_str1 + i2 * in_str2 + i3 * in_str3 +
                     i4_rd * RD_BLCK; // Calculate the index of the input tensor
        auto y_idx = i0 * out_str0 + i1 * out_str1 + i2 * out_str2 + i3 * out_str3 +
                     i4_rd * RD_BLCK; // Calculate the index of the output tensor

        *(reinterpret_cast<T*>(dat_blk)) = *(reinterpret_cast<const T*>(
            x + in_offset + x_idx)); // Read RD_BLCK number of FP_TYPE data from the input tensor

        if constexpr(!MASK) // If MASK is not enabled then generate the mask for dropout
        {
#pragma unroll
            for(auto i = 0; i < RD_BLCK; ++i)
            {
                is_kept[i] =
                    static_cast<uchar>(prng::xorwow_uniform(&cur_state) >
                                       dropout); // Generate a random number and compare it with the
                                                 // dropout probability to generate the mask
            }

            if constexpr(RSVSP) // If RSVSP is enabled then store the mask by writing RD_BLCK number
                                // of mask elements to the reserveSpace
            {
                *(reinterpret_cast<B*>(reserveSpace + rsvsp_offset + gid - i4 + i4_rd * RD_BLCK)) =
                    *(reinterpret_cast<B*>(is_kept));
            }
        }
        else
        { // If MASK is enabled then read the mask from the reserveSpace
            *(reinterpret_cast<B*>(is_kept)) = *(reinterpret_cast<const B*>(
                reserveSpace + rsvsp_offset + gid - i4 + i4_rd * RD_BLCK));
        }
// Apply the mask to the data and scale it with the scale factor.
#pragma unroll
        for(auto i = 0; i < RD_BLCK; ++i)
        {
            dat_blk[i] = static_cast<bool>(is_kept[i]) ? dat_blk[i] * static_cast<F>(scale)
                                                       : static_cast<F>(0);
        }
        // Write RD_BLCK number of FP_TYPE data to the output tensor
        *(reinterpret_cast<T*>(y + out_offset + y_idx)) = *(reinterpret_cast<T*>(dat_blk));
    }
}

template <typename IDX, typename E>
__device__ void getitembuildindices(const IDX* __restrict__ index,
                                    IDX* __restrict__ element_index,
                                    E* __restrict__ error,
                                    int32_t index_dim,
                                    int32_t indexCount,
                                    int32_t dim_size,
                                    tensor_view_t<5> index_tv,
                                    int32_t dim_offset,
                                    int32_t dim_info_offset)
{
    const uint64_t gid = threadIdx.x + blockIdx.x * blockDim.x;

    tensor_layout_t<5> ncdhw(index_tv, gid);

    if(ncdhw.layout[0] >= index_tv.size[0])
        return;

    uint64_t idx      = index_tv.get_tensor_view_idx(ncdhw);
    IDX getitem_index = index[idx];

    if(getitem_index >= 0 && getitem_index < dim_size)
    {
        element_index[(gid * indexCount) + dim_offset] = getitem_index;
    }
    else if(getitem_index >= -dim_size && getitem_index < 0)
    {
        element_index[(gid * indexCount) + dim_offset] = getitem_index + dim_size;
    }
    else
    {
        error[dim_offset] = -1;
    }

    if(gid == 0)
    {
        element_index[dim_info_offset + dim_offset] = index_dim;
    }
}

template <typename TI, typename IDX, typename TO>
__device__ void getitembwd(const TI* __restrict__ dy,
                           IDX* __restrict__ element_index,
                           TO* __restrict__ dx,
                           int32_t start_dim,
                           int32_t indexCount,
                           tensor_view_t<5> dy_tv,
                           tensor_view_t<5> dx_tv,
                           int32_t dim_info_offset,
                           int32_t offset)
{
    const uint64_t gid = threadIdx.x + blockIdx.x * blockDim.x;

    tensor_layout_t<5> ncdhw(dy_tv, gid);

    if(ncdhw.layout[0] >= dy_tv.size[0])
        return;

    tensor_layout_t<5> idx = ncdhw;

    if(indexCount > 0)
    {
        int32_t dim_cursor = ncdhw.layout[start_dim];
        int32_t i          = start_dim;
        int32_t j          = 0;

        for(; i < start_dim + indexCount; ++i, ++j)
        {
            uint64_t dim_idx = static_cast<uint64_t>(element_index[dim_info_offset + j]);
            idx.layout[dim_idx] =
                static_cast<uint64_t>(element_index[(dim_cursor * indexCount) + j]);
        }

        i          = element_index[dim_info_offset + indexCount - 1] + 1;
        dim_cursor = start_dim + 1;
        for(; i < 5; ++i, ++dim_cursor)
        {
            idx.layout[i] = ncdhw.layout[dim_cursor];
        }
    }

    idx.layout[0] += offset;
    ncdhw.layout[0] += offset;

    atomic_add_g(&dx[dx_tv.get_tensor_view_idx(idx)], dy[dy_tv.get_tensor_view_idx(ncdhw)]);
}

template <typename TIO>
__device__ void GLUFwdContiguousKernel(const TIO* input, TIO* output, uint64_t N)
{
    const TIO* inputFirstHalf  = input;
    const TIO* inputSecondHalf = input + N;
    const size_t gid           = blockIdx.x * blockDim.x + threadIdx.x;
    if(gid >= N)
        return;

    FLOAT_ACCUM val1 = CVT_FLOAT2ACCUM(inputFirstHalf[gid]);
    FLOAT_ACCUM val2 = sigmoid(CVT_FLOAT2ACCUM(inputSecondHalf[gid]));
    FLOAT_ACCUM val  = val1 * val2;
    output[gid]      = CVT_ACCUM2FLOAT(val);
}

template <typename TIO>
__device__ void
GLUBwdContiguousKernel(const TIO* input, const TIO* output_grad, TIO* input_grad, uint64_t N)
{
    const TIO* inputFirstHalf  = input;
    const TIO* inputSecondHalf = input + N;
    TIO* inputFirstHalf_grad   = input_grad;
    TIO* inputSecondHalf_grad  = input_grad + N;
    const size_t gid           = blockIdx.x * blockDim.x + threadIdx.x;
    if(gid >= N)
        return;

    FLOAT_ACCUM inputFirstHalf_v = CVT_FLOAT2ACCUM(inputFirstHalf[gid]);
    FLOAT_ACCUM sigmoid_v        = sigmoid(CVT_FLOAT2ACCUM(inputSecondHalf[gid]));
    FLOAT_ACCUM grad_v           = CVT_FLOAT2ACCUM(output_grad[gid]);

    inputFirstHalf_grad[gid] = CVT_ACCUM2FLOAT(sigmoid_v * grad_v);
    inputSecondHalf_grad[gid] =
        CVT_ACCUM2FLOAT((1 - sigmoid_v) * sigmoid_v * grad_v * inputFirstHalf_v);
}

__global__ void GLUFwdContiguousDim0(const IO_TYPE* input, IO_TYPE* output, uint64_t N)
{
    GLUFwdContiguousKernel<IO_TYPE>(input, output, N);
}

__global__ void GLUBwdContiguousDim0(const IO_TYPE* input,
                                                const IO_TYPE* output_grad,
                                                IO_TYPE* input_grad,
                                                uint64_t N)
{
    GLUBwdContiguousKernel<IO_TYPE>(input, output_grad, input_grad, N);
}

template <typename TI, typename TO>
__device__ void groupnormfwdcontiguous(const TI* __restrict__ x,
                                       const TI* __restrict__ weight,
                                       const TI* __restrict__ bias,
                                       TO* __restrict__ y,
                                       TO* __restrict__ mean,
                                       TO* __restrict__ rstd,
                                       float eps,
                                       uint64_t num_groups,
                                       uint64_t num_channels,
                                       uint64_t numel_per_channel,
                                       bool mode)
{
    /*
     * Each group works on a single channel.
     * Example)
     * x dim = {N, C, L}, normalized shape = {C, L}
     * outer_size = N, inner_size = C * L
     *
     * Example2)
     * x dim = {N, C, L}, normalized shape = {L}
     * outer_size = N * C, inner_size = L
     *
     * => gws = {outer_size * LOCAL_SIZE}, lws = {LOCAL_SIZE}
     */

    /*
     * Reduction to calculate mean and rstd
     */

    const uint64_t gid = blockIdx.x;
    const uint64_t lid = threadIdx.x;

    const size_t inner_size = numel_per_channel * num_channels / num_groups;

    FLOAT_ACCUM pmean = static_cast<FLOAT_ACCUM>(0);
    FLOAT_ACCUM pvar  = static_cast<FLOAT_ACCUM>(0);
    __shared__ FLOAT_ACCUM ltmp1[LOCAL_SIZE];
    __shared__ FLOAT_ACCUM ltmp2[LOCAL_SIZE];

    // reduce sum for mean and var
    for(uint64_t i = lid; i < inner_size; i += LOCAL_SIZE)
    {
        size_t x_idx = gid * inner_size + i;

        FLOAT_ACCUM tmp = CVT_FLOAT2ACCUM(x[x_idx]);
        pmean += tmp;
        pvar += tmp * tmp;
    }

    ltmp1[lid] = pmean;
    ltmp2[lid] = pvar;
    __syncthreads();
    for(uint32_t i = LOCAL_SIZE >> 1; i > 0; i >>= 1)
    {
        if(lid < i)
        {
            ltmp1[lid] += ltmp1[lid + i];
            ltmp2[lid] += ltmp2[lid + i];
        }
        __syncthreads();
    }
    pmean             = ltmp1[0] / inner_size;
    pvar              = ltmp2[0] / inner_size - pmean * pmean;
    FLOAT_ACCUM prstd = rsqrt(pvar + FLOAT_ACCUM(eps));

    if(lid == 0)
    {
        if(mean)
            mean[gid] = CVT_ACCUM2FLOAT(pmean);
        if(rstd)
            rstd[gid] = CVT_ACCUM2FLOAT(prstd);
    }

    // forward calculation
    for(uint64_t i = lid; i < inner_size; i += LOCAL_SIZE)
    {
        size_t idx = gid * inner_size + i;

        FLOAT_ACCUM pweight;
        FLOAT_ACCUM pbias;

        size_t c = mode ? (idx / numel_per_channel) % num_channels : 0;
        pweight  = mode ? CVT_FLOAT2ACCUM(weight[c]) : CVT_FP32_2ACCUM(1.0f);
        pbias    = mode ? CVT_FLOAT2ACCUM(bias[c]) : static_cast<FLOAT>(0);

        FLOAT_ACCUM val = (CVT_FLOAT2ACCUM(x[idx]) - pmean) * prstd * pweight + pbias;
        y[idx]          = CVT_ACCUM2FLOAT(val);
    }
}

template <typename DTYPE>
__device__ void kthvalueFwd(const DTYPE* input,
                            DTYPE* output,
                            size_t* indices,
                            size_t k,
                            size_t dim_size,
                            size_t dim_stride,
                            size_t output_size,
                            tensor_view_t<4> input_tv,
                            tensor_view_t<5> output_tv,
                            tensor_view_t<5> indices_tv)
{
    /*
     * Input : {N, C, D, H, W}. Select dim: 2(D)
     * Output/indices : {N, C, H, W} or {N, C, 1, H, W} (if keepDim param in miopen.h = True)
     * Each lws handle dim_size elements to find the kth value.
     * Lws = {256 or 512, 1, 1}
     * Gws = {A * B * D * E * lws.x, 1, 1},
     */
    using RADIX_TYPE = typename RadixType<DTYPE>::type;

    const int RADIX_BITS = 2;
    const int RADIX_SIZE = 1 << RADIX_BITS;
    const int RADIX_MASK = RADIX_SIZE - 1;

    size_t lid = threadIdx.x;
    size_t gid = blockIdx.x;
    if(gid >= output_size)
    {
        return;
    }

    __shared__ size_t lsum[LOCAL_SIZE][RADIX_SIZE];
    __shared__ DTYPE lval;
    __shared__ size_t lidx;
    size_t counts[RADIX_SIZE];
    RADIX_TYPE desired_mask = 0;
    RADIX_TYPE desired      = 0;

    tensor_layout_t<4> layout(input_tv, gid);
    auto idx = input_tv.get_tensor_view_idx(layout);

    for(int pos = sizeof(RADIX_TYPE) * 8 - RADIX_BITS; pos >= 0; pos -= RADIX_BITS)
    {
        for(size_t& count : counts)
        {
            count = 0;
        }

        for(size_t i = lid; i < dim_size; i += LOCAL_SIZE)
        {
            size_t input_idx = idx + i * dim_stride;
            RADIX_TYPE val   = encode<DTYPE>(input[input_idx]);
            if((val & desired_mask) == desired)
            {
                ++counts[GetBitFieldImpl<RADIX_BITS>(val, pos)];
            }
        }

        for(size_t i = 0; i < RADIX_SIZE; ++i)
        {
            lsum[lid][i] = counts[i];
        }
        __syncthreads();
        for(size_t i = LOCAL_SIZE >> 1; i > 0; i >>= 1)
        {
            if(lid < i)
            {
                for(size_t j = 0; j < RADIX_SIZE; ++j)
                {
                    lsum[lid][j] += lsum[lid + i][j];
                }
            }
            __syncthreads();
        }
        for(size_t i = 0; i < RADIX_SIZE; ++i)
        {
            counts[i] = lsum[0][i];
        }
        __syncthreads();

        bool found = false;
        // Process in ascending order
        for(size_t j = 0; j < RADIX_SIZE; ++j)
        {
            if(counts[j] < k)
            {
                k -= counts[j];
                continue;
            }
            // Answer is inside this count
            if(counts[j] == 1 || pos == 0)
            {
                // 1. counts[j] == 1
                // We found an unique answer.
                // 2. pos == 0
                // There are multiple answers so we return any of them
                for(size_t i = lid; i < dim_size; i += LOCAL_SIZE)
                {
                    size_t input_idx = idx + i * dim_stride;
                    DTYPE val_ori    = input[input_idx];
                    RADIX_TYPE val   = encode<DTYPE>(val_ori);
                    if((val & desired_mask) == desired &&
                       GetBitFieldImpl<RADIX_BITS>(val, pos) == j)
                    {
                        // For case 2, this will be non-deterministic.
                        lval = val_ori;
                        lidx = i;
                    }
                }
                found = true;
                break;
            }
            desired      = SetBitFieldImpl<RADIX_TYPE>(desired, j, pos);
            desired_mask = SetBitFieldImpl<RADIX_TYPE>(desired_mask, RADIX_MASK, pos);
            break;
        }
        if(found)
            break;
    }

    __syncthreads();
    if(lid == 0)
    {
        auto output_layout                                   = tensor_layout_t<5>(output_tv, gid);
        auto indices_layout                                  = tensor_layout_t<5>(indices_tv, gid);
        output[output_tv.get_tensor_view_idx(output_layout)] = lval;
        indices[indices_tv.get_tensor_view_idx(indices_layout)] = lidx;
    }
}

template <typename TI, typename TO>
__device__ void layernormfwdcontiguous(const TI* __restrict__ x,
                                       const TI* __restrict__ weight,
                                       const TI* __restrict__ bias,
                                       TO* __restrict__ y,
                                       TO* __restrict__ mean,
                                       TO* __restrict__ rstd,
                                       float eps,
                                       uint64_t inner_size,
                                       int32_t mode)
{
    /*
     * Each group works on a single channel.
     * Example)
     * x dim = {N, C, L}, normalized shape = {C, L}
     * outer_size = N, inner_size = C * L
     *
     * Example2)
     * x dim = {N, C, L}, normalized shape = {L}
     * outer_size = N * C, inner_size = L
     *
     * => gws = {outer_size * LOCAL_SIZE}, lws = {LOCAL_SIZE}
     */

    /*
     * Reduction to calculate mean and rstd
     */

    const uint64_t gid = blockIdx.x;
    const uint64_t lid = threadIdx.x;

    FLOAT_ACCUM pmean = static_cast<FLOAT_ACCUM>(0);
    FLOAT_ACCUM pvar  = static_cast<FLOAT_ACCUM>(0);
    __shared__ FLOAT_ACCUM ltmp1[LOCAL_SIZE];
    __shared__ FLOAT_ACCUM ltmp2[LOCAL_SIZE];

    // reduce sum for mean and var
    for(uint64_t i = lid; i < inner_size; i += LOCAL_SIZE)
    {
        size_t x_idx = gid * inner_size + i;

        FLOAT_ACCUM tmp = CVT_FLOAT2ACCUM(x[x_idx]);
        pmean += tmp;
        pvar += tmp * tmp;
    }

    ltmp1[lid] = pmean;
    ltmp2[lid] = pvar;
    __syncthreads();
    for(uint32_t i = LOCAL_SIZE >> 1; i > 0; i >>= 1)
    {
        if(lid < i)
        {
            ltmp1[lid] += ltmp1[lid + i];
            ltmp2[lid] += ltmp2[lid + i];
        }
        __syncthreads();
    }
    pmean             = ltmp1[0] / inner_size;
    pvar              = ltmp2[0] / inner_size - pmean * pmean;
    FLOAT_ACCUM prstd = rsqrt(pvar + FLOAT_ACCUM(eps));

    if(lid == 0)
    {
        if(mean)
            mean[gid] = CVT_ACCUM2FLOAT(pmean);
        if(rstd)
            rstd[gid] = CVT_ACCUM2FLOAT(prstd);
    }

    // forward calculation
    for(uint64_t i = lid; i < inner_size; i += LOCAL_SIZE)
    {
        size_t idx = gid * inner_size + i;

        FLOAT_ACCUM pweight;
        FLOAT_ACCUM pbias;

        pweight = (mode == MIOPEN_ELEMENTWISE_AFFINE) ? CVT_FP32_2ACCUM(1.0f)
                                                      : CVT_FLOAT2ACCUM(weight[i]);
        pbias =
            (mode == MIOPEN_ELEMENTWISE_AFFINE) ? static_cast<FLOAT>(0) : CVT_FLOAT2ACCUM(bias[i]);

        FLOAT_ACCUM val = (CVT_FLOAT2ACCUM(x[idx]) - pmean) * prstd * pweight + pbias;
        y[idx]          = CVT_ACCUM2FLOAT(val);
    }
}

template <typename TI, typename TO>
__device__ void addlayernormfwdcontiguous(const TI* __restrict__ x,
                                          const TI* __restrict__ x2,
                                          const TI* __restrict__ weight,
                                          const TI* __restrict__ bias,
                                          TO* __restrict__ y,
                                          TO* __restrict__ mean,
                                          TO* __restrict__ rstd,
                                          float eps,
