template <typename DTYPE, int REDUCTION_T>
__device__ void multimarginlossforward2d(const DTYPE* __restrict__ I,
                                         const uint64_t* __restrict__ T,
                                         const DTYPE* __restrict__ W,
                                         void* __restrict__ O,
                                         const long p,
                                         const float margin,
                                         tensor_view_t<2> I_tv,
                                         tensor_view_t<1> T_tv,
                                         tensor_view_t<1> W_tv,
                                         tensor_view_t<1> O_tv)
{
    const uint64_t gid = threadIdx.x + blockIdx.x * blockDim.x;

    size_t N = I_tv.size[0], C = I_tv.size[1];
    size_t n = gid;
    if(n >= N)
        return;

    FLOAT_ACCUM loss = 0;
    size_t y         = T[T_tv.get_tensor_view_idx({n})];
    if(y >= C)
    {
        // TODO: need to handle invalid target index value
        return;
    }

    FLOAT_ACCUM Iny = CVT_FLOAT2ACCUM(I[I_tv.get_tensor_view_idx({n, y})]);
    FLOAT_ACCUM Wy  = CVT_FLOAT2ACCUM(W[W_tv.get_tensor_view_idx({y})]);

    for(size_t c = 0; c < C; c++)
    {
        if(y == c)
            continue;
        FLOAT_ACCUM t = margin - Iny + CVT_FLOAT2ACCUM(I[I_tv.get_tensor_view_idx({n, c})]);
        if(t < 0)
            continue;
        if(p == 2)
            t = t * t;
        t = Wy * t;
        loss += t;
    }
    loss /= C;
    switch(REDUCTION_T)
    {
    case 0: static_cast<DTYPE*>(O)[O_tv.get_tensor_view_idx({n})] = CVT_ACCUM2FLOAT(loss); break;
    case 1: static_cast<FLOAT_ACCUM*>(O)[n] = loss; break;
    case 2: static_cast<FLOAT_ACCUM*>(O)[n] = loss / N; break;
    default: break;
    }
}

template <typename TI, typename TO, uint32_t NDIMS, bool SingleWeight>
__device__ void PReLUBackward(const TI* __restrict__ input,
                              const TI* __restrict__ weight,
                              const TO* __restrict__ output_grad,
                              TI* __restrict__ input_grad,
                              FLOAT_ACCUM* __restrict__ weight_grad_collector,
                              uint64_t N,
                              tensor_view_t<NDIMS> input_tv,
                              tensor_view_t<1> weight_tv,
                              tensor_view_t<NDIMS> output_grad_tv,
                              tensor_view_t<NDIMS> input_grad_tv)
{
    uint64_t gid = blockIdx.x * blockDim.x + threadIdx.x;
    if(gid >= N)
        return;

    auto tensor_layout  = tensor_layout_t<NDIMS>(input_tv, gid);
    FLOAT_ACCUM input_v = CVT_FLOAT2ACCUM(input[input_tv.get_tensor_view_idx(tensor_layout)]);
    FLOAT_ACCUM grad_v =
        CVT_FLOAT2ACCUM(output_grad[output_grad_tv.get_tensor_view_idx(tensor_layout)]);

    if(input_grad != nullptr)
    {
        FLOAT_ACCUM weight_v = CVT_FLOAT2ACCUM(
            weight[SingleWeight ? 0 : weight_tv.get_tensor_view_idx({tensor_layout.layout[1]})]);
        FLOAT_ACCUM input_grad_v = input_v > 0 ? grad_v : weight_v * grad_v;
        input_grad[input_grad_tv.get_tensor_view_idx(tensor_layout)] =
            CVT_ACCUM2FLOAT(input_grad_v);
    }
    if(weight_grad_collector != nullptr)
    {
        weight_grad_collector[gid] = input_v > 0 ? 0 : input_v * grad_v;
    }
}

template <typename TI, typename TO, ReduceCalculationOp_t op>
__device__ void calculationparallelfwdcontiguous(const TI* __restrict__ x,
                                                 TO* __restrict__ y,
                                                 uint64_t output_numel,
                                                 uint64_t reduce_size,
                                                 uint64_t parallelism_size,
                                                 uint64_t inner_size,
                                                 bool nanPropagation)
{
    const uint64_t gid = threadIdx.x + blockIdx.x * blockDim.x;
    if(gid >= parallelism_size * output_numel)
        return;

    uint64_t n = inner_size * parallelism_size;

    uint64_t slice_id       = gid / n;
    uint64_t slice_local_id = gid % n;

    uint64_t input_idx = slice_id * inner_size * reduce_size + slice_local_id;

    uint64_t parallel_id = slice_local_id / inner_size;

    FLOAT_ACCUM calculation = static_cast<FLOAT_ACCUM>(0);
    for(uint64_t k = parallel_id; k < reduce_size; k += parallelism_size)
    {
        FLOAT_ACCUM val = CVT_FLOAT2ACCUM(x[input_idx]);
        if(nanPropagation && isnan(val))
        {
            val = static_cast<FLOAT_ACCUM>(0);
        }
        reduce_func<FLOAT_ACCUM, op>{}.calculate(calculation, val);
        input_idx += inner_size * parallelism_size;
    }

    y[gid] = CVT_ACCUM2FLOAT(calculation);
}

__global__ void CalculationParallelFwdContiguous(const INPUT_TYPE* __restrict__ x,
                                                            OUTPUT_TYPE* __restrict__ y,
                                                            uint64_t output_numel,
                                                            uint64_t reduce_size,
                                                            uint64_t parallelism_size,
                                                            uint64_t inner_size,
                                                            bool nanPropagation)
{
